float CvLegMin() { return clampf(g_cvLegMin, 0.2f, 0.85f); }
// the gaze (HeadGaze: the head's child to the head joint) back to elevation e0 (deg over the mesh's level), wgt of the way, CV_HEAD_HOLD_MAX
// at most; 35 % in the neck, the rest in the head about its own joint (as HeadUp turns it): its heading is left as the pose has it
bool CvHeadHold(float e0, float wgt) {
    if (!g_cvHeadHold || wgt <= 0.001f || g_neck < 0 || g_head < 0 || g_uarm[0] < 0 || g_uarm[1] < 0) return false;
    if (!BoneUnder(g_head, g_neck) || BoneUnder(g_uarm[0], g_neck) || BoneUnder(g_uarm[1], g_neck)) return false;   // (a rig whose arms hang off the neck: not turned)
    V3 g;
    if (!HeadGaze(g_Ct, g)) return false;
    const float gh = sqrtf(g.x * g.x + g.y * g.y);
    if (gh < 0.05f) return false;
    const float el = atan2f(g.z, gh) * 57.2957795f;
    const float d = clampf(clampf(e0, -60.0f, 10.0f) - el, -CV_HEAD_HOLD_MAX, CV_HEAD_HOLD_MAX) * clampf(wgt, 0.0f, 1.0f);
    if (!std::isfinite(d) || fabsf(d) < 0.3f) return false;
    const float er = (el + d) * 0.01745329f;
    const V3 want = v3(g.x / gh * cosf(er), g.y / gh * cosf(er), sinf(er));
    TurnComp(g_neck, qscale(qfromto(g, want), 0.35f));
    V3 g2;
    if (HeadGaze(g_Ct, g2)) TurnComp(g_head, qfromto(g2, want));
    return true;
}
   // (v132) HJN_Cave("arm")'s grab: its kind for the mesh's left / right hand, seconds, cm (0 = no grab of the native half's)
