                float* t = (float*)(data + an * 48);
                const Q4 q1 = qslerpTo(qnorm(q4(t[0], t[1], t[2], t[3])), g_Ct[ft].q, wa); const V3 p1 = lerp(v3(t[4], t[5], t[6]), g_Ct[ft].p, wa);
                if (!finite3(p1) || !std::isfinite(q1.x + q1.y + q1.z + q1.w)) continue;
