    if (!C.outAt && now > C.until) { C.outAt = now; Log("caveman: no mount %llu ms after Y -- the board goes back to the hand", now - C.t0); }
    const float w = C.outAt ? 1.0f - clampf((float)(now - C.outAt) / 120.0f, 0.0f, 1.0f) : 1.0f;
    if (w <= 0.0f) { CvEnd("back in the hand"); return; }
