            const V3 sh = sub(g_Ct[ft].p, g_Ct[ca].p); const float sl = len(sh);    // old line to the new: the game's foot IK left it up to 36 deg off), the foot kept as drawn
            const V3 ax = qrot(qnorm(g_Ct[ca].q), g_shinAx[s]);
