                    const float turn = off * clampf(3.0f * w, 0.0f, 1.0f) * clampf((WR_SHIN_AIM_MAX + WR_SHIN_AIM_FADE - off) / WR_SHIN_AIM_FADE, 0.0f, 1.0f);   /* (w14 wallleg) S2. faded past WR_SHIN_AIM_MAX */
                    const Q4 fq0 = g_Ct[ft].q; const V3 fp0 = g_Ct[ft].p;
