    for (int i = 0; i < 15; i++) if (bones[i] >= 0) least = fminf(least, room(g_Ct[bones[i]].p));
    R.bodyClear = least; R.bodyClearMin = fminf(R.bodyClearMin, least); R.reachMin = fminf(R.reachMin, R.reachK);
    R.pelvisOver = WrToWorld(M, g_Ct[P0].p).z - WrToWorld(M, g_dp).z;
    R.pelvisDz = g_Ct[P0].p.z - gameZ;
