// (v140) the round of 20 Oct's own self-test: the deck flat, the way off turned and the body's line on fixed numbers (no game memory)
int WallRideSelfTest(char* out, size_t n) {
    int checks = 0; const char* fail = nullptr;
    auto nr = [](float a, float b, float t) { return std::isfinite(a) && fabsf(a - b) <= t; };
    // 1 the deck flat on the wall: 90, an overshoot past it half taken off (10 at the most)
    if (!(nr(WrFlatTilt(80.0f), 90.0f, 1e-4f) && nr(WrFlatTilt(96.0f), 87.0f, 1e-4f) && nr(WrFlatTilt(130.0f), 85.0f, 1e-4f))) fail = "WrFlatTilt: 90, the overshoot half off";
    checks++;
    // 2 the way off: 30 deg out from the wall at 450 along keeps that speed and the vertical; 0 = along it with WallRidePopOut out
    if (!fail) { const V3 v = WrExitVel(v3(1, 0, 0), v3(0, 1, 0), 450.0f, -60.0f, 30.0f, 100.0f); if (!(nr(len(flat(v)), 450.0f, 0.01f) && nr(atan2f(v.y, v.x) * 57.2957795f, 30.0f, 0.01f) && nr(v.z, -60.0f, 1e-4f))) fail = "WrExitVel: turned 30 deg out from the wall"; }
    checks++;
    if (!fail) { const V3 v = WrExitVel(v3(1, 0, 0), v3(0, 1, 0), 450.0f, -60.0f, 0.0f, 100.0f); if (!(nr(v.x, 450.0f, 1e-3f) && nr(v.y, 100.0f, 1e-3f) && nr(v.z, -60.0f, 1e-4f))) fail = "WrExitVel: along the wall with WallRidePopOut"; }
    checks++;
    // 3 the line: legs of 83.8 at 92 %, the feet 20 cm to either side of the hips' middle along their line, the hip joints 9: sqrt(77.1^2 - 11^2)
    if (!fail && !nr(WrLineRho(0.92f, 83.8f, 20.0f, 9.0f), sqrtf(0.92f * 83.8f * 0.92f * 83.8f - 121.0f), 0.01f)) fail = "WrLineRho: along the line from the ankles";
    checks++;
    if (!fail && !nr(WrLineRho(0.92f, 83.8f, 5.0f, 9.0f), 0.92f * 83.8f, 0.01f)) fail = "WrLineRho: the feet inside the hips' width";
    checks++;
    // 4 the slide: the feet 11 and 21 cm out past each hip, 60 under -> slid 5 toward the farther one: both legs one length
    if (!fail) {
        const float s = WrLineSlide(v3(0, 11, -60), v3(0, -21, -60), v3(0, 1, 0));
        const V3 a0 = sub(v3(0, 11, -60), v3(0, s, 0)), a1 = sub(v3(0, -21, -60), v3(0, s, 0));
        if (!(nr(s, -5.0f, 1e-3f) && nr(len(a0), len(a1), 1e-3f))) fail = "WrLineSlide: both legs one length";
    }
    checks++;
    // 5 the stomach's twist: the shoulders 30 deg round from the hips about the spine
    if (!fail && !nr(WrTwist(v3(1, 0, 0), v3(cosf(0.5235988f), sinf(0.5235988f), 0.0f), v3(0, 0, 1)), 30.0f, 0.01f)) fail = "WrTwist: 30 deg";
    checks++;
    if (fail) { snprintf(out, n, "FAIL %s", fail); return 0; }
    snprintf(out, n, "ok %d checks", checks);
    return checks;
}
// (v140) HJN_Wall("ride", line, lineReach %, kneeTurn deg, flat, exitAngle deg, fallGuard): the round of 20 Oct's settings (WallRideLine,
// WallRideLineReach, WallRideKneeTurn, WallRideFlat, WallRideExitAngle, WallRideFallGuard), clamped again here; the pose takes them between
// rides. Its self-test failing turns the line, the flat deck and the turned way off off (builds 236-241's ride); the falling bail is kept
int WallRideCfgTake(const double* a, int got) {
    if (g_sigMode || !g_hooked) return -1;                                       // (WallCfg says why, once)
    if (got < 6) { Log("wallride: the ride's own settings take 6 numbers, %d came -- not taken", got); return 0; }
    for (int i = 0; i < 6; i++) if (!std::isfinite(a[i])) { Log("wallride: one of the ride's own settings is not a number -- not taken"); return 0; }
    if (g_wrRideSelf == 0) {
        char st[160]; const int r = WallRideSelfTest(st, sizeof(st));
        g_wrRideSelf = (r > 0) ? 1 : -1;
        Log("wallride: the deck flat on the wall, the way off turned and the body's line: self-test %s%s", st, r > 0 ? "" : " -- they are off (builds 236-241's ride)");
    }
    const bool selfOk = g_wrRideSelf > 0;
    WrRideCfg c = {};
    c.line = (a[0] != 0.0 && selfOk) ? 1 : 0; c.lineReach = clampf((float)a[1], 80.0f, 97.0f) * 0.01f; c.kneeTurn = clampf((float)a[2], 0.0f, 90.0f);
    c.flat = (a[3] != 0.0 && selfOk) ? 1 : 0; c.exitAng = selfOk ? clampf((float)a[4], 0.0f, 60.0f) : 0.0f; c.fall = (a[5] != 0.0) ? 1 : 0;
    AcquireSRWLockExclusive(&g_wrLock); g_wrRideIn = c; ReleaseSRWLockExclusive(&g_wrLock);
    InterlockedExchange(&g_wrRideNew, 1);
    if (!g_wrRideTold || memcmp(&c, &g_wrRideSaid, sizeof(c)) != 0) {
        g_wrRideTold = true; g_wrRideSaid = c;
        char body[260], ex[120];
        if (c.line && g_wrBtOn) snprintf(body, sizeof(body), "one straight line from the ankles at WallRideLean (WallRideLine 1): the legs %.0f %% of their length along it (WallRideLineReach: replaced by WallRideLegReach, below), WallRideKneeTurn %.0f (no longer read: WallRideKneeWay, below); the board keeps its height under it (its target hooked)", c.lineReach * 100.0f, c.kneeTurn);
        else if (c.line) snprintf(body, sizeof(body), "NOT one line (WallRideLine 1, but the board's height hook is not in): the hips keep the game's height, as builds 236-241 drew them");
        else snprintf(body, sizeof(body), "as builds 236-241 drew it (WallRideLine 0: WallRideLean and WallRideLeanLegs)");
        if (c.exitAng > 0.5f) snprintf(ex, sizeof(ex), "turned %.0f deg out from the wall, the board's heading with it (WallRideExitAngle)", c.exitAng);
        else snprintf(ex, sizeof(ex), "along the wall with WallRidePopOut's drift (WallRideExitAngle 0)");
        Log("wallride: the ride's own settings: the body %s; the deck %s; the way off %s; the board's own falling bail %s -- from the next ride", body,
            c.flat ? "flat on the wall, its nose along it (WallRideFlat 1)" : "at WallRideDeckTilt with the animation's nose-in (WallRideFlat 0)", ex,
            c.fall ? "held while you ride and take off from the ground (WallRideFallGuard 1: the wheels may touch the wall)" : "the game's (WallRideFallGuard 0: the wheels on the wall bail you)");
    }
    return 6;
}
