        snprintf(b, sizeof(b), "%d %.1f %.0f", on ? 1 : 0, std::isfinite(g_wr.clearNow) ? (double)g_wr.clearNow : 999.0, std::isfinite(g_wr.measV) ? (double)g_wr.measV : 0.0);
