    {   /* a bent knee, never a straight leg reaching for it (as 253's) */
        const int f = T.ufDropFoot ? 1 : 0, hj = g_thigh[f], cj = g_calf[f], fj = g_foot[f];
        if (hj >= 0 && cj >= 0 && fj >= 0 && hj < MAX_BONES && cj < MAX_BONES && fj < MAX_BONES) { const V3 Q = UfReach(g_C[hj].p, P, len(sub(g_C[cj].p, g_C[hj].p)) + len(sub(g_C[fj].p, g_C[cj].p))); if (finite3(Q)) P = Q; }
    }
