        const V3 Dp = UfDropAt(dp, qrot(dq, v3(1.0f, 0.0f, 0.0f)), T.ufDropY, T.ufE0, T.ufDropX, HalfWidth());
        if (finite3(Dp)) P = add(Dp, mul(sub(P, Dp), UfSmooth(te / UF_IN)));
