                {   /* (261 review) the correction (deck frame) changes at most UF_TOUCH_RATE cm/s: no one-pose twitch; a shoe that leaves in the slab put out the last way */
                    const float dt = (T.ufTouchT > 0.0) ? clampf((float)(now - T.ufTouchT), 0.004f, 0.05f) : 0.0167f;
                    V3 C = qinv(dq, sub(P, P0)); const V3 dC = sub(C, T.ufTouchC); const float dl = len(dC), st = UF_TOUCH_RATE * dt;
                    if (std::isfinite(dl) && dl > st) { C = add(T.ufTouchC, mul(dC, st / dl)); P = add(P0, qrot(dq, C)); const V3 Ps = UfNoIntoP(P, rel, ns, dq, dp, HalfLen(), HalfWidth(), CentreX(), pref); if (finite3(Ps)) P = Ps; }
                    const V3 Cn = qinv(dq, sub(P, P0)); if (finite3(Cn)) T.ufTouchC = Cn; T.ufTouchT = now;
                }
                if (c > 0.99f && te <= T.ufFollow) { T.ufTouchN++; if (g0 < 1e8f && g0 > T.ufTouchGap) T.ufTouchGap = g0; }
                if (mv > T.ufTouchMove) T.ufTouchMove = mv;
