    // the stick mode, the stance, the back-foot stick
    const int mode = ih[ALT_IH_MODE];
    const bool modeOk = mode == 1 || mode == 2;
    if (!modeOk && g_altCfg.on && !g_altModeTold) { g_altModeTold = true; AltNews("refused", "not on: the stick mode is %s (the alt set is made for the front/back-foot and the left/right-foot modes)", mode == 3 ? "Legacy" : "not set"); }
