AltKickS AltKickAt(const AltKickPath& P, int role, float u) {   // one foot at u (0..1 of the flip), the samples' straight blend, the ways made unit again
    const int r = role & 1;
    const float x = clampf(u, 0.0f, 1.0f) * (float)(ALT_KP_N - 1);
    const int i = (int)fminf(floorf(x), (float)(ALT_KP_N - 2));
    const float f = x - (float)i;
    const AltKickS& a = P.s[i][r]; const AltKickS& b = P.s[i + 1][r];
    AltKickS o = { a.al + (b.al - a.al) * f, a.toe + (b.toe - a.toe) * f, a.dn + (b.dn - a.dn) * f, a.kal + (b.kal - a.kal) * f, a.kto + (b.kto - a.kto) * f, a.kup + (b.kup - a.kup) * f,
                   a.fal + (b.fal - a.fal) * f, a.fto + (b.fto - a.fto) * f, a.fup + (b.fup - a.fup) * f };
    const float kl = sqrtf(o.kal * o.kal + o.kto * o.kto + o.kup * o.kup), fl = sqrtf(o.fal * o.fal + o.fto * o.fto + o.fup * o.fup);
    if (kl > 1e-3f) { o.kal /= kl; o.kto /= kl; o.kup /= kl; } else { o.kal = 0.0f; o.kto = 1.0f; o.kup = 0.0f; }   // (a way through nothing: the knee toward the toes)
    if (fl > 1e-3f) { o.fal /= fl; o.fto /= fl; o.fup /= fl; } else { o.fal = 0.0f; o.fto = 0.6f; o.fup = -0.8f; }
    return o;
}
void AltKickMarks(AltKickPath& P) {               // the hold (the mean of 35..65 % of the flip): u1 the first sample from uA on within 6 cm of it with both feet, u2 the last; uA both ankles within 50 cm under the hips
    float h[2][3] = { { 0, 0, 0 }, { 0, 0, 0 } }; int m = 0;
    for (int i = 0; i < ALT_KP_N; i++) {
        const float u = (float)i / (float)(ALT_KP_N - 1);
        if (u < 0.35f - 1e-4f || u > 0.65f + 1e-4f) continue;
        for (int r = 0; r < 2; r++) { h[r][0] += P.s[i][r].al; h[r][1] += P.s[i][r].toe; h[r][2] += P.s[i][r].dn; }
        m++;
    }
    for (int r = 0; r < 2; r++) for (int j = 0; j < 3; j++) h[r][j] /= (float)(m > 0 ? m : 1);
    auto off = [&](int i) { float o = 0.0f; for (int r = 0; r < 2; r++) { const float a = P.s[i][r].al - h[r][0], b = P.s[i][r].toe - h[r][1], c = P.s[i][r].dn - h[r][2]; o = fmaxf(o, sqrtf(a * a + b * b + c * c)); } return o; };
    P.uA = 0.5f;
    for (int i = 0; i < ALT_KP_N; i++) if (P.s[i][0].dn <= 50.0f && P.s[i][1].dn <= 50.0f) { P.uA = (float)i / (float)(ALT_KP_N - 1); break; }
    P.u1 = 0.35f; P.u2 = 0.65f;
    for (int i = 0; i < ALT_KP_N; i++) { const float u = (float)i / (float)(ALT_KP_N - 1); if (u + 1e-4f >= P.uA && off(i) <= 6.0f) { P.u1 = u; break; } }
    for (int i = ALT_KP_N - 1; i >= 0; i--) if (off(i) <= 6.0f) { P.u2 = (float)i / (float)(ALT_KP_N - 1); break; }
    if (P.u1 > 0.65f) P.u1 = 0.65f;
    if (P.u2 < P.u1) P.u2 = P.u1;
}
float AltKickStart(const AltKickPath& P, float dnLead) {   // where the replay starts: the first u (up to the hold) whose leading ankle is as high under the hips as the game has it as the turn begins
    if (!(dnLead > 0.0f && dnLead < 200.0f)) return fminf(P.uA, P.u1);
    float prev = AltKickAt(P, 0, 0.0f).dn;
    if (prev <= dnLead) return 0.0f;
    const float step = P.u1 / 48.0f;
    for (int j = 1; j <= 48; j++) {
        const float u = step * (float)j, d = AltKickAt(P, 0, u).dn;
        if (d <= dnLead) return u - step + step * (prev - dnLead) / fmaxf(prev - d, 1e-3f);   // (between the two steps, straight)
        prev = d;
    }
    return P.u1;
}
// the phase of the replay: u0 where it starts, tT s since the turn began, E its degrees, rem the degrees still to turn (-1: not known --
// a manual spin not caught yet), up the REAL deck's angle from upright (it trails the target by 40-60 deg), done: the turn is over
float AltKickPhase(const AltKickPath& P, float u0, float tT, float E, float rem, float up, bool done) {
    const float D = clampf(P.D, 0.3f, 1.5f), uA = clampf(u0, 0.0f, P.u1);
    const float tk = fmaxf((P.u1 - uA) * D, 0.03f), th = fmaxf((P.u2 - P.u1) * D, 0.03f);
    const float kick = clampf(fmaxf(tT / tk, E / 120.0f), 0.0f, 1.0f);   // the kick at the flip's own pace, done by 120 deg of the turn at the latest
    float u = (kick < 1.0f) ? uA + (P.u1 - uA) * Sm01(kick) : P.u1 + (P.u2 - P.u1) * clampf((tT - tk) / th, 0.0f, 1.0f);   // then the hold at its pace, its end held for as long as the board spins
    const float back = done ? 1.0f : (rem >= 0.0f && rem < 180.0f) ? clampf((80.0f - up) / 60.0f, 0.0f, 1.0f) : 0.0f;   // the way home: the end known and near, as the real deck comes from 80 to 20 deg off upright
    if (back > 0.0f) u += (P.u2 + (1.0f - P.u2) * back - u) * Sm01(back);
    return clampf(u, 0.0f, 1.0f);
}
// (v134 review) the way home goes one way: once the replay is past its hold's end (the feet on their way home) it never turns back. The
// real deck it follows does not always come upright once: a catch just past a whole turn eases the board BACK through upright (segment
// 16, 0.67-0.82 s: the deck 9 -> 40 -> 35 -> 13 deg off upright), and the replay went 0.75 -> 0.96 -> 0.88 -> 1: on your second double
// flip's path the leading foot came in 59 -> 44 cm out along the board and kicked out again to 55, the trailing -31 -> -11 -> -22 toward the toes
float AltKickHome(float u, float uPrev, float u2) { return (uPrev > u2 + 1e-3f && u < uPrev) ? uPrev : u; }
// the room a foot's shoe has from the board tumbling about its across axis Ya (unit, + toward the toes): its heel (6 cm behind the ankle
// along the foot), ankle and toe tip (20 past it), those over the board's width (within hw + 2 of its middle across), against the disk the
// board sweeps (radius R about its middle) -- cm, 1e9 = beside the board; yLo / yHi: the shoe's points across, from the board's middle
float AltKickRoom(V3 c, V3 Ya, float R, float hw, V3 ankle, V3 fway, float* yLo, float* yHi) {
    const V3 pts[3] = { sub(ankle, mul(fway, 6.0f)), ankle, add(ankle, mul(fway, 20.0f)) };
    float room = 1.0e9f, lo = 1.0e9f, hi = -1.0e9f;
    for (int i = 0; i < 3; i++) {
        const V3 v = sub(pts[i], c); const float y = dot(v, Ya);
        lo = fminf(lo, y); hi = fmaxf(hi, y);
        if (fabsf(y) > hw + 2.0f) continue;
        room = fminf(room, len(sub(v, mul(Ya, y))) - R);
    }
    if (yLo) *yLo = lo;
    if (yHi) *yHi = hi;
    return room;
}
// one foot of the replay: its place (the hips + the sample in the monster's frame: Xr along the board toward this foot's own end, Yk
// toward the toes, up), the knee's way and the foot's way there; the guard: where the shoe is in the tumbling board's disk, pushed
// sideways (st.side: +1 toward the toes, -1 the heels, chosen once a trick -- the side away from the other foot's if that one has one,
// else the nearer -- up to guardCap cm, eased 2.5 cm a pose); the place moving at most 650 cm/s (your double flips' kick is 570 at its fastest:
// a catch that brings the end of the replay all at once does not snap the feet home in a pose); kept within 97 % of the leg's reach from the hip
struct AltKickFootIn { V3 Pp, Xr, Yk, c, Ya, hip; float R, hw, guardCap, reach, lift, dt; };
struct AltKickFootSt { int side; float push; V3 last; int has; };
struct AltKickFootOut { V3 F, pole, fway; float room, need; };
AltKickFootOut AltKickFoot(const AltKickS& S, const AltKickFootIn& in, AltKickFootSt& st, int otherSide) {
    AltKickFootOut o;
    const V3 Z = v3(0.0f, 0.0f, 1.0f);
    const V3 T = add(add(in.Pp, mul(in.Xr, S.al)), add(mul(in.Yk, S.toe), mul(Z, -S.dn + fmaxf(in.lift, 0.0f))));
    o.pole = norm(add(add(mul(in.Xr, S.kal), mul(in.Yk, S.kto)), mul(Z, S.kup)));
    o.fway = norm(add(add(mul(in.Xr, S.fal), mul(in.Yk, S.fto)), mul(Z, S.fup)));
    float lo = 0.0f, hi = 0.0f;
    const float room0 = AltKickRoom(in.c, in.Ya, in.R, in.hw, T, o.fway, &lo, &hi);
    float need = 0.0f;
    if (room0 < 0.0f && in.guardCap > 0.0f) {
        const float nToe = in.hw + 2.0f - lo, nHeel = hi + in.hw + 2.0f;   // the shoe out past the board's toe-side edge / heel-side edge
        if (st.side == 0) st.side = (otherSide != 0) ? -otherSide : (nToe <= nHeel ? 1 : -1);
        need = clampf(st.side > 0 ? nToe : nHeel, 0.0f, in.guardCap);
    }
    st.push = fmaxf(st.push + clampf(need - st.push, -2.5f, 2.5f), 0.0f);
    V3 F = add(T, mul(in.Ya, (st.side >= 0 ? 1.0f : -1.0f) * st.push));
    if (st.has) { const V3 mv = sub(F, st.last); const float ml = len(mv), cap = 650.0f * clampf(in.dt, 0.004f, 0.05f); if (ml > cap) F = add(st.last, mul(mv, cap / ml)); }
    st.last = F; st.has = 1;
    const V3 d = sub(F, in.hip); const float dl = len(d);
    if (in.reach > 1.0f && dl > 0.97f * in.reach) F = add(in.hip, mul(d, 0.97f * in.reach / dl));
    o.F = F; o.need = need;
    o.room = AltKickRoom(in.c, in.Ya, in.R, in.hw, F, o.fway, nullptr, nullptr);
    return o;
}
// a flip learned from the game's own (n poses at t[], each foot's sample as AltKickS, raw) resampled to the path's 13 over its time D
void AltKickResample(const float* t, const AltKickS (*q)[2], int n, AltKickPath& P) {
    P.D = t[n - 1];
    for (int j = 0; j < ALT_KP_N; j++) {
        const float tt = P.D * (float)j / (float)(ALT_KP_N - 1);
        int i = 0;
        while (i < n - 2 && t[i + 1] < tt) i++;
        const float span = t[i + 1] - t[i], f = (span > 1e-6f) ? clampf((tt - t[i]) / span, 0.0f, 1.0f) : 0.0f;
        for (int r = 0; r < 2; r++) {
            const AltKickS& a = q[i][r]; const AltKickS& b = q[i + 1][r];
            AltKickS s = { a.al + (b.al - a.al) * f, a.toe + (b.toe - a.toe) * f, a.dn + (b.dn - a.dn) * f, a.kal + (b.kal - a.kal) * f, a.kto + (b.kto - a.kto) * f, a.kup + (b.kup - a.kup) * f,
                           a.fal + (b.fal - a.fal) * f, a.fto + (b.fto - a.fto) * f, a.fup + (b.fup - a.fup) * f };
            const float kl = sqrtf(s.kal * s.kal + s.kto * s.kto + s.kup * s.kup), fl = sqrtf(s.fal * s.fal + s.fto * s.fto + s.fup * s.fup);
            if (kl > 1e-3f) { s.kal /= kl; s.kto /= kl; s.kup /= kl; }
            if (fl > 1e-3f) { s.fal /= fl; s.fto /= fl; s.fup /= fl; }
            P.s[j][r] = s;
        }
    }
}
// is a learned flip one the monster may copy? 0 = yes; else why not (why): (a) each foot out to its own end of the board through the
// hold (10 cm at least: one forward, one back -- never both on one side of the hips); (b) not both swung over 20 cm the same way
// across (both in front of the body, or both behind it: "both of them forward"), from where they stood as the flip began, nor both held
// over 20 cm to one side of the hips (v134 review); (c) with
// the board's middle `depth` cm under the hips (dToe toward the toes), no shoe in its tumbling disk (radius hl + room) by more than
// the guard (guard cm sideways) can take it out at any sample of the hold
int AltKickCheck(const AltKickPath& P, float depth, float hl, float hw, float room, float guard, char* why, size_t n) {
    if (why && n) why[0] = 0;
    if (!(P.D >= 0.12f && P.D <= 1.5f)) { if (why) snprintf(why, n, "its time %.2f s is not a flip's", P.D); return 1; }
    float h[2][2] = { { 0, 0 }, { 0, 0 } }; int m = 0;
    for (int i = 0; i < ALT_KP_N; i++) {
        const float u = (float)i / (float)(ALT_KP_N - 1);
        if (u + 1e-4f < P.u1 || u - 1e-4f > P.u2) continue;
        for (int r = 0; r < 2; r++) { h[r][0] += P.s[i][r].al; h[r][1] += P.s[i][r].toe; }
        m++;
    }
    if (m < 1) { if (why) snprintf(why, n, "no hold found"); return 2; }
    for (int r = 0; r < 2; r++) { h[r][0] /= (float)m; h[r][1] /= (float)m; }
    if (h[0][0] < 10.0f || h[1][0] < 10.0f) {
        if (why) snprintf(why, n, "the %s foot only %.0f cm out along the board from the hips (one foot must go out to each end)", h[0][0] < h[1][0] ? "leading" : "trailing", fminf(h[0][0], h[1][0]));
        return 3;
    }
    const float line = 0.5f * (P.s[0][0].toe + P.s[0][1].toe), d0 = h[0][1] - line, d1 = h[1][1] - line;
    if (fabsf(d0) > 20.0f && fabsf(d1) > 20.0f && d0 * d1 > 0.0f) {
        if (why) snprintf(why, n, "both feet went toward the %s (%+.0f / %+.0f cm from where they stood): one in front of the body, one behind", d0 > 0.0f ? "toes" : "heels", d0, d1);
        return 4;
    }
    // (v134 review) ...and not both held over 20 cm to one side of the HIPS. 17:55:54's flip -- the one every monster of build 235 copied,
    // "both of them forward" -- holds its feet +34 / +25 cm toward the toes from the hips, but only +12 / +3 from where they stood (on a
    // board 19 cm in front of the hips): the rule above kept it, and only (a) refused it, its trailing foot 9 cm out along the board
    // against the 10 asked. Your double flips hold +12 / +50, +12 / -32, +69 / +18 and -26 / +18 (one foot far to one side, the other
    // near the hips' line): kept
    if (fabsf(h[0][1]) > 20.0f && fabsf(h[1][1]) > 20.0f && h[0][1] * h[1][1] > 0.0f) {
        if (why) snprintf(why, n, "both feet held toward the %s of the hips (%+.0f / %+.0f cm): one in front of the body, one behind", h[0][1] > 0.0f ? "toes" : "heels", h[0][1], h[1][1]);
        return 4;
    }
    if (depth > 1.0f) {
        const V3 c = v3(0.0f, P.dToe, -depth), Ya = v3(0.0f, 1.0f, 0.0f);
        float worst = 0.0f; int wr = 0; float wu = 0.0f;
        for (int i = 0; i < ALT_KP_N; i++) {
            const float u = (float)i / (float)(ALT_KP_N - 1);
            if (u + 1e-4f < P.u1 || u - 1e-4f > P.u2) continue;
            for (int r = 0; r < 2; r++) {
                const AltKickS& s = P.s[i][r];
                float lo = 0.0f, hi = 0.0f;
                const float rm = AltKickRoom(c, Ya, hl + room, hw, v3(s.al, s.toe, -s.dn), norm(v3(s.fal, s.fto, s.fup)), &lo, &hi);
                if (rm >= 0.0f) continue;
                const float side = fminf(hw + 2.0f - lo, hi + hw + 2.0f) - guard;
                const float clash = fminf(-rm, side);
                if (clash > worst) { worst = clash; wr = r; wu = u; }
            }
        }
        if (worst > 3.0f) {
            if (why) snprintf(why, n, "the %s foot would be %.0f cm inside the tumbling board's way at %.0f %% of it with the board %.0f cm under the hips", wr == 0 ? "leading" : "trailing", worst, wu * 100.0f, depth);
            return 5;
        }
    }
    return 0;
}
// ---- (v134) end of the kick's pure part
constexpr int ALT_LEARN_N = 4, ALT_LEARN_S = 96;
struct AltLearnT {
    bool on; double t0, tPrev; int n; V3 Xd, Yt, mpPrev; float lead, outS[2]; bool leadOk;
    float t[ALT_LEARN_S]; AltKickS q[ALT_LEARN_S][2]; float dtoe[ALT_LEARN_S];   // (v134) per pose and FOOT (the roles are given at the flip's end, once its way is known): the place, the knee's way, the foot's way; the deck's middle toward the toes
    AltKickPath kept[ALT_LEARN_N]; int keptN, keptHead; LONG learned, told, rejected; int useNext; bool filled;   // (v134) what the monster replays, in turn: your four double flips first, each in its turn replaced by a flip learned this run (the oldest first)
};
AltLearnT g_alearn = {};
V3 g_kickX = { 1, 0, 0 }, g_kickY = { 0, 1, 0 };
AltKickPath g_kickCur = {}; AltKickFootSt g_kickSt[2] = {}; float g_kickU0 = 0.0f, g_kickU = 0.0f; double g_kickT0 = 0.0, g_kickTPrev = 0.0;   // (v134) the path this monster replays, its feet's guard and speed, where the replay began and stands
// (v134) WHICH FLIP A MONSTER COPIES: the next of the kept, in turn. Your four double flips of 17:38 are four different kicks of one shape (the
// trailing foot swung in front of the body; behind it; the leading foot in front, its leg straight; the leading foot behind) -- taken in turn
// the monsters show all four as you did them. The most recent alone would make every monster copy whatever flip came last -- a plain
// kickflip whose feet barely leave the board, or 17:55:54's (both feet in front of the body, the trailing one 3-9 cm out along the board:
// build 235's every monster, and the checks below now refuse it) -- and one odd flip would then repeat until the next.
int AltKickPick(AltKickPath& out, int* idx) {     // -> how many are kept; out = the path this monster replays, idx = which
    AltLearnT& L = g_alearn;
    if (!L.filled) {
        for (int i = 0; i < ALT_LEARN_N; i++) { L.kept[i] = kAltKickPaths[i & 3]; AltKickMarks(L.kept[i]); }
        L.keptN = ALT_LEARN_N; L.keptHead = 0; L.filled = true;
    }
    const int i = (L.useNext++) % L.keptN;
    out = L.kept[i];
    if (idx) *idx = i;
    return L.keptN;
}
bool AltFlipLive(bool grab, bool wall) {          // a flip of the game's own is turning in the air and the alt set is idle: learn from it, record it
    if (grab || wall || g_bail || g_pelvis < 0 || g_foot[0] < 0 || g_foot[1] < 0) return false;
    if (g_alt.t.phase != 0 || g_alt.s.in != 0) return false;
    const uint8_t* bm = BoardMC();
    if (!bm || !PtrOk(bm, 0x8a0)) return false;
    return bm[BM_MODE] == 3 && (bm[ALT_BM_FLAGS] & 0x08) != 0;
}
void AltFlipLearnEnd(const char* why) {
    AltLearnT& L = g_alearn;
    if (!L.on) return;
    L.on = false;
    const float D = (L.n > 0) ? L.t[L.n - 1] : 0.0f;
    if (D < 0.12f || D > 1.5f || !L.leadOk || L.n < 6) return;
    if (!(L.outS[0] * L.lead > 0.0f))              // the roles: the leading foot (the way you travelled) first
        for (int i = 0; i < L.n; i++) { const AltKickS s = L.q[i][0]; L.q[i][0] = L.q[i][1]; L.q[i][1] = s; }
    AltKickPath P = {};
    AltKickResample(L.t, L.q, L.n, P);
    float dt = 0.0f; int m = 0;
    for (int i = 0; i < L.n; i++) if (L.t[i] >= 0.3f * D && L.t[i] <= 0.7f * D) { dt += L.dtoe[i]; m++; }
    P.dToe = (m > 0) ? dt / (float)m : 22.0f;
    SYSTEMTIME st; GetLocalTime(&st);
    P.when = (int)st.wHour * 10000 + (int)st.wMinute * 100 + (int)st.wSecond; P.learned = 1;
    AltKickMarks(P);
    char whyTxt[220];
    int bad = AltKickCheck(P, (g_altLowDepth > 0.5f) ? g_altLowDepth : 42.0f, HalfLen(), HalfWidth(), fmaxf(g_altCfg.mSplay, 0.0f) + 2.0f, g_altGuardCm, whyTxt, sizeof(whyTxt));
    for (int i = 0; i < ALT_KP_N && !bad; i++) for (int r = 0; r < 2; r++)
        if (!(P.s[i][r].dn > -20.0f && P.s[i][r].dn < 110.0f && fabsf(P.s[i][r].al) < 90.0f && fabsf(P.s[i][r].toe) < 110.0f)) { bad = 6; snprintf(whyTxt, sizeof(whyTxt), "a pose of it out of the board's reach"); break; }
    const AltKickS h0 = AltKickAt(P, 0, 0.5f * (P.u1 + P.u2)), h1 = AltKickAt(P, 1, 0.5f * (P.u1 + P.u2));
    if (bad) {
        L.rejected++;
        if (InterlockedIncrement(&L.told) <= 12)
            Log("alt flips: a flip of the game's (%.2f s, %s) NOT kept for the monster: %s (its hold: the leading foot %.0f cm out along the board from the hips, %+.0f toward the toes; the trailing %.0f / %+.0f)", D, why, whyTxt, h0.al, h0.toe, h1.al, h1.toe);
        return;
    }
    // (v135) NOT KEPT. "The feet on the flips need to be just like the double flips. Cannot accept anything else" (19 Oct, build 236):
    // its monsters of 22:51-22:52 replayed your double flips (the knees, ankles and toes within a few cm of segment 49's, measured), and
    // from 22:55 on your plain kickflips took their places one by one ("kept for the monster in place of your double flip of 17:38:05")
    // -- the 23:01 dolphins copied plain flips. Your four double flips are the only feet now; a flip of yours is only said.
    if (InterlockedIncrement(&L.told) <= 12)
        Log("alt flips: a flip of the game's seen (%.2f s, %s): NOT kept -- the monster's and the dolphin's feet are your four double flips of 18 Oct 17:38, always (build 237)", D, why);
    return;
    if (!L.filled) { int dummy = 0; AltKickPath tmp; AltKickPick(tmp, &dummy); L.useNext = 0; }   // (the defaults in first, so this one takes the oldest's place)
    const int slot = L.keptHead;
    const AltKickPath& was = L.kept[slot];
    const int wasWhen = was.when, wasLearned = was.learned;
    L.kept[slot] = P; L.keptHead = (L.keptHead + 1) % ALT_LEARN_N;
    L.learned++;
    if (InterlockedIncrement(&L.told) <= 12)
        Log("alt flips: learned the feet of a flip of the game's (%.2f s, %s; %d poses): its hold %.0f..%.0f %% of it, the leading foot %.0f cm out along the board from the hips, %+.0f toward the toes, %.0f under them; the trailing %.0f / %+.0f / %.0f -- kept for the monster in place of %s %02d:%02d:%02d (%ld learned this run)",
            D, why, L.n, P.u1 * 100.0f, P.u2 * 100.0f, h0.al, h0.toe, h0.dn, h1.al, h1.toe, h1.dn, wasLearned ? "the flip learned at" : "your double flip of", wasWhen / 10000, (wasWhen / 100) % 100, wasWhen % 100, (long)L.learned);
}
void AltFlipLearn(void* mesh) {                   // one pose of a flip of the game's (g_C is the game's pose)
    AltLearnT& L = g_alearn;
    const double now = NowS();
    if (!L.on || now - L.tPrev > 0.1) {           // a new flip: the board's frame at its first pose
        if (L.on) AltFlipLearnEnd("a gap");
        const Q4 sq = g_dq; const V3 sp = g_dp;
        const bool ok = DeckXf(mesh);
        const V3 X = ok ? flat(qrot(g_dq, v3(1, 0, 0))) : v3(0, 0, 0), c = ok ? add(g_dp, qrot(g_dq, v3(CentreX(), 0.0f, 0.0f))) : v3(0, 0, 0);
        g_dq = sq; g_dp = sp;
        if (!ok || len(X) < 0.3f) return;
        L.on = false; L.n = 0; L.leadOk = false; L.lead = 1.0f;
        L.Xd = norm(X);
        V3 Y = norm(cross(v3(0, 0, 1), L.Xd));
        float ts = 0.0f;
        for (int k = 0; k < 2; k++) if (g_toe[k] >= 0) ts += dot(sub(g_C[g_toe[k]].p, g_C[g_foot[k]].p), Y);
        if (fabsf(ts) < 0.5f) { float ya = 0.0f; for (int k = 0; k < 2; k++) ya += dot(sub(g_C[g_foot[k]].p, c), Y); ts = (ya > 0.0f) ? -1.0f : 1.0f; }   // (the ankles ride on the heels' side)
        L.Yt = mul(Y, ts >= 0.0f ? 1.0f : -1.0f);
        for (int k = 0; k < 2; k++) L.outS[k] = (dot(sub(g_C[g_foot[k]].p, c), L.Xd) >= 0.0f) ? 1.0f : -1.0f;
        if (L.outS[0] == L.outS[1]) { const bool z = dot(sub(g_C[g_foot[0]].p, g_C[g_foot[1]].p), L.Xd) >= 0.0f; L.outS[0] = z ? 1.0f : -1.0f; L.outS[1] = -L.outS[0]; }
        L.mpPrev = *(const V3*)((const uint8_t*)mesh + SC_C2W + 0x10);
        L.on = true; L.t0 = now; L.tPrev = now; L.n = 0; L.leadOk = false;
    }
    if (!L.leadOk) {                              // the way you travel, from the mesh's move since the first pose: the leading foot
        const V3 mp = *(const V3*)((const uint8_t*)mesh + SC_C2W + 0x10);
        const Q4 mq = qnorm(*(const Q4*)((const uint8_t*)mesh + SC_C2W));
        const V3 v = flat(sub(mp, L.mpPrev));
        if (len(v) > 0.5f) {
            const V3 XdW = flat(qrot(mq, L.Xd));
            L.lead = (dot(v, XdW) >= 0.0f) ? 1.0f : -1.0f; L.leadOk = true;
        }
        else if (now - L.t0 > 0.05) { L.lead = 1.0f; L.leadOk = true; }   // (standing still: the nose's foot leads)
    }
    L.tPrev = now;
    if (L.n >= ALT_LEARN_S) return;
    if (L.n > 0 && (float)(now - L.t0) - L.t[L.n - 1] < 0.0155f) return;   // (v134 review) one sample per 1/60 s at the most: the path is the flip's WHOLE way now, and 96
                                                   // poses of every pose cut a flip off at 0.64 s at 150 fps (1.07 s at 90): its hold's end and its way home lost; so 96 cover 1.5 s at any rate (60 fps: every pose, as before)
    const V3 Pp = g_C[g_pelvis].p;
    L.t[L.n] = (float)(now - L.t0);
    for (int k = 0; k < 2; k++) {                 // (v134) by foot; the knee's way off the hip-ankle line and the foot's way with the place
        const V3 Xr = mul(L.Xd, L.outS[k]), A = g_C[g_foot[k]].p, d = sub(A, Pp);
        V3 kn = v3(0.0f, 0.0f, 1.0f), fw = v3(0.0f, 0.6f, -0.8f);
        if (g_thigh[k] >= 0 && g_calf[k] >= 0) {
            const V3 hf = sub(A, g_C[g_thigh[k]].p), kv = sub(g_C[g_calf[k]].p, g_C[g_thigh[k]].p); const float h2 = dot(hf, hf);
            const V3 kp = (h2 > 1.0f) ? sub(kv, mul(hf, dot(kv, hf) / h2)) : kv;
            if (len(kp) > 1e-3f) kn = norm(kp);
        }
        if (g_toe[k] >= 0) { const V3 tv = sub(g_C[g_toe[k]].p, A); if (len(tv) > 1e-3f) fw = norm(tv); }
        L.q[L.n][k] = AltKickS{ dot(d, Xr), dot(d, L.Yt), -d.z, dot(kn, Xr), dot(kn, L.Yt), kn.z, dot(fw, Xr), dot(fw, L.Yt), fw.z };
    }
    {   // (v134) the deck's middle toward the toes from the hips (the learn's check takes the board there)
        const Q4 sq = g_dq; const V3 sp = g_dp;
        L.dtoe[L.n] = DeckXf(mesh) ? dot(sub(add(g_dp, qrot(g_dq, v3(CentreX(), 0.0f, 0.0f))), Pp), L.Yt) : 22.0f;
        g_dq = sq; g_dp = sp;
    }
    L.n++;
}
bool SafeAltFlipLive(bool grab, bool wall) { __try { return AltFlipLive(grab, wall); } __except (EXCEPTION_EXECUTE_HANDLER) { return false; } }
void SafeAltFlipLearn(void* mesh, bool live) {
    __try { if (live) AltFlipLearn(mesh); else if (g_alearn.on && NowS() - g_alearn.tPrev > 0.05) AltFlipLearnEnd("its flip over"); }
    __except (GrabFilter(GetExceptionCode())) { g_alearn.on = false; }
}
// (v134) the kick, pose by pose (PosePass on g_Ct, through AltTuck): the frame, the leading foot and the flip it replays latched on the
// trick's first pose with the feet off; each foot to its sample at the replay's phase (AltKickFoot), the leg solved there by the legs'
// share with the flip's knee and the foot swung to where the flip pointed it
bool AltKick(void* mesh) {
    const float w0 = clampf(g_altLegW, 0.0f, 1.0f);
    if ((w0 < 0.005f && g_kickW < 0.005f) || g_pelvis < 0 || !mesh || !PtrOk(mesh, SC_C2W + 0x30)) { g_kickSt[0].push = g_kickSt[1].push = 0.0f; g_kickW = 0.0f; return false; }
    const Q4 sq = g_dq; const V3 sp = g_dp;
    if (!DeckXf(mesh)) { g_dq = sq; g_dp = sp; return false; }
    const V3 c = add(g_dp, qrot(g_dq, v3(CentreX(), 0.0f, 0.0f)));
    const V3 Ya = norm(qrot(g_dq, v3(0.0f, 1.0f, 0.0f)));        // the board's across axis: the one it tumbles about
    const V3 Xn = qrot(g_dq, v3(1.0f, 0.0f, 0.0f));
    g_dq = sq; g_dp = sp;
    const V3 Pp = g_Ct[g_pelvis].p;
    const double now = NowS();
    if (g_altLegSeenN != g_altLegN) {             // latched on the trick's first pose with the feet off: the frame, the leading foot, the flip it replays and where
        g_altLegSeenN = g_altLegN;
        V3 X = flat(Xn); if (len(X) < 0.3f) X = v3(1, 0, 0);
        g_kickX = norm(X); const V3 Y = norm(cross(v3(0, 0, 1), g_kickX));
        float ts = 0.0f; int nt = 0;
        for (int k = 0; k < 2; k++) if (g_foot[k] >= 0 && g_toe[k] >= 0) { ts += dot(sub(g_Ct[g_toe[k]].p, g_Ct[g_foot[k]].p), Y); nt++; }
        if (nt > 0 && fabsf(ts) > 0.5f) { g_altToeSign = ts > 0.0f ? 1.0f : -1.0f; g_altToeFrom = 1; }
        else {
            float ya = 0.0f; int na = 0;
            for (int k = 0; k < 2; k++) if (g_foot[k] >= 0) { ya += dot(sub(g_Ct[g_foot[k]].p, c), Y); na++; }
            if (na > 0 && fabsf(ya) > 0.5f) { g_altToeSign = ya > 0.0f ? -1.0f : 1.0f; g_altToeFrom = 2; } else { g_altToeSign = 1.0f; g_altToeFrom = 3; }
        }
        g_kickY = mul(Y, g_altToeSign);
        g_altLeadFoot = -1;
        if (g_foot[0] >= 0 && g_foot[1] >= 0)
            g_altLeadFoot = (g_altLead * dot(sub(g_Ct[g_foot[0]].p, c), g_kickX) >= g_altLead * dot(sub(g_Ct[g_foot[1]].p, c), g_kickX)) ? 0 : 1;
        int idx = 0;
        const int kept = AltKickPick(g_kickCur, &idx);
        g_kickU0 = AltKickStart(g_kickCur, (g_altLeadFoot >= 0) ? Pp.z - g_Ct[g_foot[g_altLeadFoot]].p.z : -1.0f);   // the replay begins where the game has the leading foot
        g_kickU = g_kickU0; g_kickT0 = now; g_kickTPrev = now; g_kickW = 0.0f;
        g_kickSt[0] = g_kickSt[1] = AltKickFootSt{ 0, 0.0f, v3(0.0f, 0.0f, 0.0f), 0 };
        AltKickInfo& I = g_altKickInfo;
        I = AltKickInfo{}; I.when = g_kickCur.when; I.learned = g_kickCur.learned; I.idx = idx; I.n = kept; I.u0 = g_kickU0;
        for (int r = 0; r < 2; r++) { const AltKickS h = AltKickAt(g_kickCur, r, 0.5f * (g_kickCur.u1 + g_kickCur.u2)); I.holdAl[r] = h.al; I.holdToe[r] = h.toe; }
        g_altKickSrc = idx + 1; g_altKickAl[0] = I.holdAl[0]; g_altKickAl[1] = I.holdAl[1]; g_altKickGot[0] = g_altKickGot[1] = 0.0f;
    }
    const float dtp = clampf((float)(now - g_kickTPrev), 0.0f, 0.05f);
    g_kickTPrev = now;
    float u = AltKickPhase(g_kickCur, g_kickU0, g_altKickT, g_altKickE, g_altKickRem, g_altKickUp, g_altKickDone);
    const float du = fmaxf(dtp, 0.004f) / 0.1f;                  // (the whole replay in 0.1 s at the quickest)
    u = AltKickHome(clampf(u, g_kickU - du, g_kickU + du), g_kickU, g_kickCur.u2); g_kickU = u; g_altKickUNow = u;   // (v134 review: once on its way home, never back out)
    const float w = clampf(fmaxf(w0 * Sm01((float)(now - g_kickT0) / 0.08f), g_kickW - fmaxf(dtp, 0.004f) / 0.10f), 0.0f, 1.0f);   // in over 0.08 s from the latch; let go over 0.1 s at the quickest (the game's foot IK comes back in 2-3 poses as the deck comes upright)
    g_kickW = w;
    const float hl = HalfLen(), hw = HalfWidth();
    const float R = hl + fmaxf(g_altSplayCm, 0.0f) + 2.0f + 0.6f * hl * sinf(fminf(g_altDriftPk, 30.0f) * 0.0174532925f);   // the disk the tumbling board sweeps: AltMonsterSplay cm of room, its drift's swing
    const V3 Yt = mul(Ya, g_altToeSign);                                                // across the board, + toward the toes
    const float gScale = g_altKickDone ? 0.0f : clampf((g_altKickUp - 30.0f) / 30.0f, 0.0f, 1.0f);   // the guard only while the board tumbles (the real deck 30-60+ deg off upright): coming home the feet are meant to be over it
    bool moved = false;
    float roomMin = 1.0e9f;
    for (int k = 0; k < 2; k++) {
        const int th = g_thigh[k], ca = g_calf[k], ft = g_foot[k];
        if (th < 0 || ca < 0 || ft < 0) continue;
        const int role = (g_altLeadFoot < 0) ? k : (k == g_altLeadFoot ? 0 : 1);
        AltKickFootIn in;
        in.Pp = Pp; in.Xr = mul(g_kickX, (role == 0 ? 1.0f : -1.0f) * (g_altLead >= 0.0f ? 1.0f : -1.0f)); in.Yk = g_kickY; in.c = c; in.Ya = Yt; in.hip = g_Ct[th].p;
        in.R = R; in.hw = hw; in.guardCap = 0.0f * gScale; /* (v135) no sideways guard: the feet exactly as your double flips; (v136) this note was a // comment in v135 and swallowed the rest of the line -- the reach, the lift and the time were never set: the feet ~100 cm over the hips */ in.reach = len(sub(g_Ct[ca].p, g_Ct[th].p)) + len(sub(g_Ct[ft].p, g_Ct[ca].p)); in.lift = g_altTuckOwn; in.dt = dtp;
        const AltKickFootOut o = AltKickFoot(AltKickAt(g_kickCur, role, u), in, g_kickSt[k], g_kickSt[1 - k].side);
        if (g_kickSt[k].push > g_altKickGot[role]) g_altKickGot[role] = g_kickSt[k].push;
        g_altOutNow[k] = (g_kickSt[k].side >= 0 ? 1.0f : -1.0f) * g_kickSt[k].push;
        if (o.room < 1.0e8f) roomMin = fminf(roomMin, o.room);
        const V3 gp = sub(g_Ct[ca].p, lerp(g_Ct[th].p, g_Ct[ft].p, 0.5f));                 // the knee's way: the pose's own, to the flip's by the share
        V3 pole = lerp((len(gp) > 1e-3f) ? norm(gp) : o.pole, o.pole, w);
        pole = (len(pole) > 0.2f) ? norm(pole) : ((w > 0.5f || len(gp) <= 1e-3f) ? o.pole : norm(gp));
        Q4 fq = g_Ct[ft].q;
        if (g_toe[k] >= 0 && len(g_Lt[g_toe[k]].p) > 1e-3f) {                             // the foot swung to where the flip pointed it (its own roll about itself kept)
            const V3 fwd = qrot(qnorm(fq), norm(g_Lt[g_toe[k]].p));
            fq = qslerpTo(fq, qnorm(qmul(qfromto(fwd, o.fway), fq)), w);
        }
        Leg(k, lerp(g_Ct[ft].p, o.F, w), fq, v3(0.0f, 0.0f, 0.0f), &pole);
        moved = true;
    }
    g_altShoeNow = roomMin;
    if (moved && w > 0.9f) { g_altSplayPoses++; if (roomMin < 1.0e8f) g_altShoeMin = fminf(g_altShoeMin, roomMin); }
    else if (moved) g_altSplayPoses++;
    return moved;
}
// ==== the leg tuck (PosePass, on g_Ct): each foot drawn toward its hip by the tuck and (alt2: design 5.2) moved out along the
// board's tumble axis until its shoe clears the board's side by AltMonsterSplay cm, the leg solved to it; the clearance measured
bool AltTuck(void* mesh) {
    if (!(g_altTuckCm > 0.5f) || !g_boardOk) return false;
    if (g_altSplayStyle == 0) return AltKick(mesh);   // (v132) the feet kicked out as the game's flips kick them
    const float tuck = g_altTuckOwn, w = clampf(g_altLegW, 0.0f, 1.0f);
    bool spl = g_altSplayCm > 0.05f && w > 0.01f && mesh != nullptr && PtrOk(mesh, SC_C2W + 0x30);
    V3 c = v3(0.0f, 0.0f, 0.0f), Yd = v3(0.0f, 1.0f, 0.0f), Xd = v3(1.0f, 0.0f, 0.0f);
    if (spl) {                                     // the deck's middle and the tumble axis in the mesh's space (g_dq / g_dp as they were before)
        const Q4 sq = g_dq; const V3 sp = g_dp;
        if (DeckXf(mesh)) {
            c = add(g_dp, qrot(g_dq, v3(CentreX(), 0.0f, 0.0f)));
            Xd = qrot(g_dq, v3(1.0f, 0.0f, 0.0f));
            const uint8_t* m = (const uint8_t*)mesh;
            const Q4 mq = qnorm(*(const Q4*)(m + SC_C2W)); const V3 ms = *(const V3*)(m + SC_C2W + 0x20);
            V3 a = qinv(mq, g_altAxisW);
            a = v3(a.x / (fabsf(ms.x) > 1e-3f ? ms.x : 1.0f), a.y / (fabsf(ms.y) > 1e-3f ? ms.y : 1.0f), a.z / (fabsf(ms.z) > 1e-3f ? ms.z : 1.0f));
            if (finite3(a) && len(a) > 0.5f) Yd = norm(a); else spl = false;
        }
        else spl = false;
        g_dq = sq; g_dp = sp;
    }
    if (spl && g_altLegSeenN != g_altLegN) {      // latched on this trick's first splayed pose: the toes' side of the axis, the leading foot
        g_altLegSeenN = g_altLegN;
        float ts = 0.0f; int nt = 0;
        for (int k = 0; k < 2; k++) if (g_foot[k] >= 0 && g_toe[k] >= 0) { ts += dot(sub(g_Ct[g_toe[k]].p, g_Ct[g_foot[k]].p), Yd); nt++; }
        if (nt > 0 && fabsf(ts) > 0.5f) { g_altToeSign = ts > 0.0f ? 1.0f : -1.0f; g_altToeFrom = 1; }
        else {
            float ya = 0.0f; int na = 0;
            for (int k = 0; k < 2; k++) if (g_foot[k] >= 0) { ya += dot(sub(g_Ct[g_foot[k]].p, c), Yd); na++; }
            if (na > 0 && fabsf(ya) > 0.5f) { g_altToeSign = ya > 0.0f ? -1.0f : 1.0f; g_altToeFrom = 2; } else { g_altToeSign = 1.0f; g_altToeFrom = 3; }
        }
        g_altLeadFoot = -1;
        if (g_foot[0] >= 0 && g_foot[1] >= 0)
            g_altLeadFoot = (g_altLead * dot(sub(g_Ct[g_foot[0]].p, c), Xd) >= g_altLead * dot(sub(g_Ct[g_foot[1]].p, c), Xd)) ? 0 : 1;
    }
    const float hw = HalfWidth(), hl = HalfLen();
    const float room = hw + g_altSplayCm + 0.6f * hl * sinf(fminf(g_altDriftPk, 30.0f) * 0.0174532925f);   // (the drift swings a tip at the feet's height a few cm sideways)
    bool moved = false;
    for (int k = 0; k < 2; k++) {
        const int th = g_thigh[k], ca = g_calf[k], ft = g_foot[k];
        if (th < 0 || ca < 0 || ft < 0) continue;
        const V3 A0 = g_Ct[ft].p;
        const V3 d = sub(g_Ct[th].p, A0); const float L = len(d);
        if (!(L > 20.0f)) continue;
        V3 F = add(A0, mul(d, fminf(tuck, L * 0.35f) / L));
        g_altOutNow[k] = 0.0f;
        if (spl) {
            const float ts = g_altToeSign;
            const float yA = dot(sub(A0, c), Yd) * ts;
            const float yT = (g_toe[k] >= 0) ? dot(sub(g_Ct[g_toe[k]].p, c), Yd) * ts : yA + 15.0f;
            const bool leadK = k == g_altLeadFoot;
            const int side = AltSplaySide(g_altSplayStyle - 1, leadK);
            const float need = AltSplayNeed(side, yA, yT, room) * w;
            F = add(F, mul(Yd, ts * (float)side * need));
            g_altOutNow[k] = (float)side * need;
            float& got = g_altOutGot[leadK ? 0 : 1];
            if (need > fabsf(got)) got = (float)side * need;
        }
        Leg(k, F, g_Ct[ft].q);
        moved = true;
    }
    g_altShoeNow = 1.0e9f;
    if (spl && moved && w > 0.9f) {               // the shoes against the board's sides (in its swept disk only), as they are drawn
        g_altSplayPoses++;
        for (int k = 0; k < 2; k++) {
            const int ft = g_foot[k];
            if (ft < 0) continue;
            const V3 v = sub(g_Ct[ft].p, c);
            const float yA = dot(v, Yd) * g_altToeSign;
            const float yT = (g_toe[k] >= 0) ? dot(sub(g_Ct[g_toe[k]].p, c), Yd) * g_altToeSign : yA + 15.0f;
            if (len(sub(v, mul(Yd, dot(v, Yd)))) >= hl) continue;
            const float lo = fminf(yA - 5.0f, yT + 5.0f), hi = fmaxf(yA - 5.0f, yT + 5.0f);
            const float clear = fmaxf(lo - hw, -hw - hi);
            g_altShoeNow = fminf(g_altShoeNow, clear); g_altShoeMin = fminf(g_altShoeMin, clear);
        }
    }
    else if (spl && moved) g_altSplayPoses++;
    return moved;
}
void AltForget(const char* why) {                  // a new skater, mesh or map: nothing of the last one's alt trick is written anywhere
    if (g_alt.t.phase != 0) Log("alt flips: #%ld dropped (%s) -- nothing written back", (long)g_alt.t.n, why);
    InterlockedExchange(&g_altForgetAsk, 1);       // (the pose forgets it: zeroing it here could land inside a running AltTick)
    g_fpW = 0.0f; g_loopBits = 0; g_faW = 0.0f; g_faAnim = nullptr;   // (243) the hooks' share of a flip let go at once (and FpLive() is false until the pose forgets: the note at FpStep)
}
// ---- the settings and the definitions (the Lua's thread)
int AltCfgTake(const double* a, int got) {
    if (g_sigMode || !g_hooked) {
        if (!g_altSigTold) {
            g_altSigTold = true;
            Log("alt flips: not on this build of the game (another build than Epic's 30 March exe, or the pose hook is not in): the alt set writes parts of the game that were only checked on that exe -- it stands down");
            AltNews("info", "not on this build of the game: the alt flip set stands down (the native log says why)");
        }
        return -1;
    }
    if (got < ALT_CFG_MIN) { Log("alt flips: the settings take %d to %d numbers, %d came -- not taken", ALT_CFG_MIN, ALT_CFG_N, got); return 0; }
    double full[ALT_CFG_N];                        // (alt2) an older main.lua's 11: the rest at their defaults
    AltCfgDefaults(full);
    for (int i = 0; i < got && i < ALT_CFG_N; i++) full[i] = a[i];
    AltCfg c = kAltCfg0;
    if (!AltCfgFrom(full, c)) { Log("alt flips: a setting is not a number -- not taken"); return 0; }
    if (g_altSelf == 0) {
        const char* fail = nullptr;
        const int k = AltSelfTestMath(&fail);
        g_altSelf = fail ? -1 : 1;
        if (fail) { g_altDead = 1; Log("alt flips: self-test FAIL %s -- the alt flip set is off", fail); AltNews("info", "the native half's self-test failed (%s): the alt flip set is off", fail); }
        else Log("alt flips: ready (native v%d): self-test ok, %d checks", kVersion, k);
    }
    AcquireSRWLockExclusive(&g_altLock); g_altCfgIn = c; ReleaseSRWLockExclusive(&g_altLock);
    InterlockedExchange(&g_altCfgNew, 1);
    if (!g_altCfgTold || memcmp(&c, &g_altCfgSaid, sizeof(c)) != 0) {
        g_altCfgTold = true; g_altCfgSaid = c;
        const char* cms[3] = { "one turn by itself", "as your game's Catch setting", "always manual" };
        const char* sps[5] = { "kicked out along the board as your own flips kick them", "sideways: the leading foot toward the toes", "sideways: the leading foot toward the heels", "sideways: both toward the heels", "sideways: both toward the toes" };
        Log("alt flips: settings %s: the back stick up past %.2f (within 40 deg of straight up) crouches for the alt set, let go inside %.2f; Monster Flip on the ollie %s (x%.2f your kickflip speed, the leading end %s first, room %.0f cm, the feet tucked %.0f cm); Nightmare Flip on the varial flip %s (its flip x%.2f); the alt names %s"
            "; Daydream Flip on the varial heel %s; the monster: its speed from your flick %s, its catch %s, the feet out %.0f cm (%s), wobble %.0f deg, drift %.0f deg%s",
            c.on ? "ON" : "off", c.engage, c.release, c.monster ? "on" : "off", c.mSpeed, c.mNoseUp ? "up" : "down", c.mClear, c.mTuck, c.night ? "on" : "off", c.nSpeed, c.names ? "on" : "off",
            c.day ? "on" : "off", c.mFlick ? "on" : "off", cms[c.mCatch], c.mSplay, sps[c.mSplayStyle], c.mWobble, c.mDrift, got < ALT_CFG_N ? " (an older main.lua sent only the first numbers: the rest at their defaults)" : "");
    }
    return got < ALT_CFG_N ? got : ALT_CFG_N;
}
int SafeAltCfg(const double* a, int got) { __try { return AltCfgTake(a, got); } __except (GrabFilter(GetExceptionCode())) { Log("alt flips: fault taking the settings"); return 0; } }
int AltDefCheck(int i, uintptr_t d, char* why, size_t n) {   // the definition the Lua found is the one its slot says (design 2.6)
    const uint8_t* p = (const uint8_t*)d;
    if (!PtrOk(p, 0x2d0)) { snprintf(why, n, "not readable"); return 0; }
    if (p[ALT_FTD_FOOT] != kAltSlotFoot[i]) { snprintf(why, n, "its foot position is %d, not %d", (int)p[ALT_FTD_FOOT], (int)kAltSlotFoot[i]); return 0; }
    const float fl = fabsf(ReadF(p, ALT_FTD_FLIP)), sc = fabsf(ReadF(p, ALT_FTD_SCOOP));
    if (i < 4 ? !(fl < 1.0f && sc < 1.0f) : !(fabsf(fl - 360.0f) < 10.0f && fabsf(sc - 180.0f) < 10.0f)) { snprintf(why, n, "its flip %.0f / scoop %.0f are not a%s's", fl, sc, i < 4 ? "n ollie" : i < 8 ? " varial flip" : " varial heel"); return 0; }   // (alt2) the varial heels: the same magnitudes
    return 1;
}
int SafeAltDefCheck(int i, uintptr_t d, char* why, size_t n) { __try { return AltDefCheck(i, d, why, n); } __except (GrabFilter(GetExceptionCode())) { snprintf(why, n, "a fault reading it"); return 0; } }
int AltDefsTake(const double* a, int got) {        // (alt2) 12 slots: the ollies, the varial flips, the varial heels (fewer numbers = the rest none)
    if (g_sigMode || !g_hooked) return -1;
    uintptr_t d[12] = {}; int okN = 0, asked = 0; char why[900] = "";
    for (int i = 0; i < 12; i++) {
        const uintptr_t p = (i < got && std::isfinite(a[i]) && a[i] > 65536.0 && a[i] < 1.8e19) ? (uintptr_t)a[i] : 0;
        if (!p) continue;
        asked++;
        char w[100] = "";
        if (SafeAltDefCheck(i, p, w, sizeof(w))) { d[i] = p; okN++; }
        else AltCat(why, sizeof(why), "%s%s: %s", why[0] ? "; " : "", kAltSlotName[i], w);
    }
    AcquireSRWLockExclusive(&g_altLock); memcpy(g_altDefIn, d, sizeof(d)); ReleaseSRWLockExclusive(&g_altLock);
    InterlockedExchange(&g_altDefsNew, 1);
    if (asked) Log("alt flips: %d of 12 trick definitions accepted%s%s", okN, why[0] ? " -- refused: " : "", why);
    else Log("alt flips: the trick definitions forgotten (a level change)");
    return okN;
}
int AltOk(double s) {
    if (g_sigMode || !g_hooked) return -1;
    if (g_altDead) return 0;
    const ULONGLONG now = GetTickCount64();
    if (std::isfinite(s) && s > 0.0) g_altOkUntil = now + (ULONGLONG)(clampf((float)s, 0.0f, 1.0f) * 1000.0f);
    else g_altOkUntil = 0;
    return 1;
}
// the self-test: the pure part's checks, then what the game's fields read now
int AltSelfTest(char* out, size_t n) {
    const char* fail = nullptr;
    const int checks = AltSelfTestMath(&fail);
    if (fail) { snprintf(out, n, "FAIL %s", fail); return -1; }
    char g[760] = "";
    uint8_t* fth = LateHandler(); const uint8_t* pc = (const uint8_t*)g_pc; const uint8_t* sk = (const uint8_t*)g_skater; const uint8_t* anim = (const uint8_t*)g_anim;
    const uint8_t* ih = (pc && PtrOk(pc, 0x7c8)) ? *(const uint8_t* const*)(pc + PC_INPUT) : nullptr;
    const uint8_t* bm = BoardMC();
    int defs = 0; for (int i = 0; i < 12; i++) if (g_altDef[i] || g_altDefIn[i]) defs++;
    if (!fth || !ih || !PtrOk(ih, 0x40) || !sk || !PtrOk(sk, 0xa40) || !anim || !PtrOk(anim, 0x600) || !bm) snprintf(g, sizeof(g), "the controller or the skater is not handed over yet; %d of 12 definitions", defs);
    else {
        const int mode = ih[ALT_IH_MODE]; const bool goofy = anim[ALT_AI_GOOFY] != 0; const uint8_t fp = sk[SK_FOOTPOS];
        const float* st = (const float*)(pc + ALT_PC_STICKS);
        const uint8_t* w = *(const uint8_t* const*)(pc + ALT_PC_WIDGET);
        const bool wOk = w && PtrOk(w, 0x330);
        const int fm = sk[ALT_SK_FLIPMODE], cm = sk[ALT_SK_CATCHMODE];
        snprintf(g, sizeof(g), "the stick mode %d (%s), the back stick %s; %s, foot position %d; the stick buffer %.2f %.2f %.2f %.2f; the trick display %s (%d pending, index %d); the board's mode %d; %d of 12 definitions; the buffer's down %s"
            "; the flip speed mode %d (%s), the catch mode %d (%s), the catch dead zone %.2f%s",
            mode, mode == 2 ? "front/back-foot" : mode == 1 ? "left/right-foot" : mode == 3 ? "Legacy: OFF" : "none: OFF", (mode == 1 || mode == 2) ? (AltBackLeft(mode, fp == 2 || fp == 4, goofy) ? "LEFT" : "RIGHT") : "-",
            goofy ? "goofy" : "regular", (int)fp, st[0], st[1], st[2], st[3], wOk ? "found" : "NOT found", wOk ? *(const int32_t*)(w + ALT_TDW_COUNT) : 0, wOk ? *(const int32_t*)(w + ALT_TDW_INDEX) : 0,
            (int)bm[BM_MODE], defs, g_alt.downSign > 0.0f ? "+1 (learned)" : "-1", fm, AltFlickModeName(fm), cm, cm == 2 ? "manual" : cm == 1 ? "auto" : "?", AltDeadZone(pc),
            (!g_sigMode && Exe()[RVA_ALT_GBFSM] == 0xE9) ? "; the game's flip-speed function is hooked by another mod (SessionTweaks' FlipSpeed): the monster takes its answer, and with its FlipSpeed on it counts the alt ollie as a flip trick for its catch rules" : "");   // (review B F4)
    }
    snprintf(out, n, "ok %d checks; %s", checks, g);
    return checks;
}
int SafeAltSelfTest(char* out, size_t n) { __try { return AltSelfTest(out, n); } __except (GrabFilter(GetExceptionCode())) { snprintf(out, n, "FAIL a fault in the self-test"); return -1; } }
// ==== HJN_Alt(op, ...) -- the Lua's door (v129; alt2: v131)
//   "cfg", on, engage, release, monster, mSpeed, mNoseUp, mClear, mTuck, night, nSpeed, names, (alt2) day, mFlick, mCatch, mSplay, mSplayStyle,
//          mWobble, mDrift (11 to 18 numbers: the rest at their defaults) -> how many were taken, 0 refused, -1 stood down
//   "defs", 12 addresses (TRICK_RGS_Ollie, TRICK_SWS_Ollie, TRICK_NLS_Nollie, TRICK_FKS_Ollie, TRICK_RGS/SWS/NLS/FKS_VarialFlip, (alt2) TRICK_RGS/SWS/NLS/FKS_VarialHeel;
//          0 = none; fewer = the rest none) -> accepted, -1 stood down
//   "ok", seconds -> 1 the window is open that long (0 = shut now), 0 not taken (the set is dead), -1 stood down
//   "news" -> the next line "<tag> <sentence>", or "" (tags: engage taken monster nightmare daydream other cancel info refused, and bail: the Lua asks the
//          game for a bail) | "state" -> "<phase -1 stood down / 0 / 1 alt crouch / 2 alt trick / 3 landed> <kind 0 / 1 monster / 2 nightmare / 3 other /
//          4 daydream> <the definition's address> <the alt trick's number> <names wanted 0/1> <the mirror now: 0 none / 1 the right stick / 2 the left>" |
//          "feet" -> the share of the game's foot IK wanted on this frame (-1 = leave it) | "end" -> 1 | "selftest" -> "ok <n> checks; <what the game reads>" or "FAIL <what>"
//   (v134) "kick", AltMonsterBoardLow, AltMonsterGuard -> 2 | "dolphin", AltDolphin, AltDolphinInput, AltDolphinSide -> 3 | "state"'s kind 5 = a Dolphin Flip,
//          (review) and its 7th number the front stick handed over turned now (the dolphin's: y -> -y at its own throw): 0 none / 1 the right stick / 2 the left;
//          (245) kind 6 = a Dolphin Flip that is the game's own varial flip (the note at AltDolVarSlot) -- HJN_Set("altdolvar", 0/1) switches it
int nAlt(const Lua& lua) {                                       // (a std::string lives here: no __try in this function, C2712)
    std::string op;
    ArgStr(lua, op);
    if (op == "cfg") {
        double a[ALT_CFG_N] = { 0 }; int got = 0;
        for (; got < ALT_CFG_N; got++) if (!ArgNum(lua, a[got])) break;
        lua.set_integer(SafeAltCfg(a, got));
        return 1;
    }
    if (op == "defs") {
        double a[12] = { 0 }; int got = 0;
        for (; got < 12; got++) if (!ArgNum(lua, a[got])) break;
        lua.set_integer(AltDefsTake(a, got));
        return 1;
    }
    if (op == "ok") { double s = 0; ArgNum(lua, s); lua.set_integer(AltOk(s)); return 1; }
    if (op == "news") { char b[ALT_NEWS_LEN]; AltNewsTake(b, sizeof(b)); lua.set_string(b); return 1; }
    if (op == "state") {
        const AltT& A = g_alt;
        const int tph = g_altForgetAsk ? 0 : A.t.phase;   // (243) a new skater, mesh or map: the trick being forgotten is not reported (the Lua lets go of its trick slot at once)
        const int ph = (g_sigMode || !g_hooked || g_altDead) ? -1 : (tph ? tph : ((A.s.in || A.sn.in) ? 1 : 0));   /* (246) + the nollie set's crouch */
        char b[128];
        const bool hn = !tph && HospNameLive(NowS());   /* (253 review) no alt trick: a driven hospital's name (kind 11, the note at HospNm) */
        snprintf(b, sizeof(b), "%d %d %llu %ld %d %d %d", ph, ((tph && !A.t.dol && A.t.kind == 9 && A.t.usSweep) ? 3 : 0) + (tph ? (A.t.dol ? (A.t.por ? 10 : 5) : A.t.kind) : 0) + (hn ? 11 : 0), (unsigned long long)(tph ? A.t.def : (hn ? g_hospNm.def : 0)), (long)A.t.n, tph ? A.t.names : (hn ? 1 : 0), (A.s.in == 1) ? (A.engLeft ? 2 : 1) : (A.sn.in == 1 && A.nMir) ? (A.nLeft ? 2 : 1) : 0, A.nFlip ? (A.nFlipLeft ? 2 : 1) : (A.fwrote && !A.nMir && !A.fwPor) ? (A.fwLeft ? 2 : 1) : 0);   // (review F10) + the mirror now: 0 none, 1 the right stick, 2 the left stick; (v134 review) + the front stick turned over now (the dolphin's), the same way
        lua.set_string(b);
        return 1;
    }
    if (op == "kick") {                         // (v134) AltMonsterBoardLow, AltMonsterGuard -> the number taken
        double a[2] = { 66.0, 10.0 }; int got = 0;
        for (; got < 2; got++) if (!ArgNum(lua, a[got])) break;
        if (got >= 1 && std::isfinite(a[0])) g_altLowDepth = (float)(a[0] < 0.0 ? 0.0 : a[0] > 95.0 ? 95.0 : a[0]);
        if (got >= 2 && std::isfinite(a[1])) g_altGuardCm = (float)(a[1] < 0.0 ? 0.0 : a[1] > 30.0 ? 30.0 : a[1]);
        lua.set_integer(got);
        return 1;
    }
    if (op == "dolphin") {                      // (v134) AltDolphin, AltDolphinInput, AltDolphinSide -> how many were taken
        double a[3] = { 1.0, 0.0, 0.0 }; int got = 0;
        for (; got < 3; got++) if (!ArgNum(lua, a[got])) break;
        if (got >= 1 && std::isfinite(a[0])) InterlockedExchange(&g_altDolOn, a[0] >= 0.5 ? 1 : 0);
        if (got >= 2 && std::isfinite(a[1])) InterlockedExchange(&g_altDolIn, a[1] < 0.5 ? 0 : a[1] < 1.5 ? 1 : 2);
        if (got >= 3 && std::isfinite(a[2])) InterlockedExchange(&g_altDolSide, a[2] >= 0.5 ? 1 : 0);
        lua.set_integer(got);
        return 1;
    }
    if (op == "borrowed" || op == "clipend") {   // (243) the Lua's words for alt trick n: your flip's animation in the trick slot for it (its loop in it: 1), or its flip over (the notes at FpStep)
        double nn = 0.0, lp = 0.0;
        ArgNum(lua, nn); ArgNum(lua, lp);
        const LONG k = (std::isfinite(nn) && nn >= 1.0 && nn < 2.0e9) ? (LONG)nn : 0;
        if (op == "borrowed") { g_fpBorrowLoop = (lp >= 0.5) ? 1 : 0; g_fpBorrowN = k; }   /* the loop's word first: FpStep reads the number */
        else g_fpClipN = k;
        lua.set_integer(k != 0 ? 1 : 0);
        return 1;
    }
    if (op == "gamefeet") { lua.set_number(GameFeet() ? 1.0 : 0.0); return 1; }   // (242) the game's feet in (AltFlipFeet and every hook they need): only then is the flip animation borrowed
    if (op == "feet") { lua.set_number(GameFeet() ? -1.0 : (double)g_altFeet); return 1; }   // (v137) the game's foot IK left as the game sets it: the feet the flip animation's
    if (op == "end") { InterlockedExchange(&g_altEndAsk, 1); lua.set_integer(1); return 1; }
    if (op == "selftest") { char b[1000]; SafeAltSelfTest(b, sizeof(b)); lua.set_string(b); return 1; }
    lua.set_integer(0);
    return 1;
}
// ==== end of the alt flip set

// ==== (v43) THE IN-GAME SETTINGS PAGES =================================================================
// "Expanded Trick Settings" in the GAME'S OWN pause menu. Stage 1 rides SessionOpenMP's pause-menu seam
// (menu_ext.h in its source: a C ABI its main.dll exports, OmpMenu_RegisterPage2, that fills the game's
// native UMG menu with the rows a guest declares -- the same way SessionTweaks gets its pages). With no
// such host loaded the rows are never shown and the ini stays the way to set things. Stage 2 is a host
// of our own (a port of that injection), so that no other mod is needed; the rows below stay as they are.
// The rows come from the Lua half (HJN_MenuPage / HJN_MenuRow), which owns the ini: what a row shows
// is what HJN_MenuValue last said, what the player changes goes into a queue the Lua drains each
// second (HJN_MenuTake) and writes to the ini. The host calls back on the GAME thread, inside SEH.
#include <psapi.h>
#pragma comment(lib, "psapi.lib")
enum { MENU_ACTION = 0, MENU_TOGGLE = 1, MENU_SLIDER = 2, MENU_PAGE = 3 };
struct OmpPageItem2 { int kind; const char* key; const char* label; const char* desc; const char* offLabel; const char* onLabel; float minValue, maxValue, step; };
typedef void (*OmpPageSelectFn)(const char* key, void* user);
typedef void (*OmpPageValueFn)(const char* key, int intValue, float floatValue, void* user);
typedef int  (*OmpPageGetFn)(const char* key, int* outInt, float* outFloat, void* user);
typedef const char* (*OmpPageStatusFn)(const char* key, void* user);
typedef int (*OmpRegisterPage2Fn)(const char* title, const OmpPageItem2* items, int nItems, OmpPageSelectFn onSelect,
                                  OmpPageValueFn onValue, OmpPageGetFn onGet, OmpPageStatusFn onStatus, void* user);
constexpr int MENU_PAGES = 12, MENU_ROWS = 48, MENU_VALS = 256;   // (247 menu) 8 -> 12 pages: Flip Tricks and Wallrides make 10 with Quick (the 9th and 10th were refused)
struct MenuRow { int kind; char key[48], label[64], desc[400], off[24], on[24]; float lo, hi, step; };   // (v100: the description 240 -> 400)
struct MenuPage { char title[64]; MenuRow row[MENU_ROWS]; OmpPageItem2 item[MENU_ROWS]; int n; };
MenuPage g_mpage[MENU_PAGES]; int g_mpageN = 0;
struct MenuVal { char key[48]; float v; }; MenuVal g_mval[MENU_VALS]; int g_mvalN = 0;
char g_mqueue[4096] = { 0 }; CRITICAL_SECTION g_mlock; bool g_mlockOk = false;
int g_mreg = 0, g_mtries = 0;
volatile int g_menuOwn = 0;                    // (v60) HJN_Set("menuown", 1): our own pages even when SessionOpenMP's seam is loaded (its menu is off in mods.txt)
void MenuLock() { if (!g_mlockOk) { InitializeCriticalSection(&g_mlock); g_mlockOk = true; } EnterCriticalSection(&g_mlock); }
void MenuUnlock() { LeaveCriticalSection(&g_mlock); }
MenuVal* MenuFind(const char* key) { for (int i = 0; i < g_mvalN; i++) if (strcmp(g_mval[i].key, key) == 0) return &g_mval[i]; return nullptr; }
int MenuKind(const char* key) {
    for (int p = 0; p < g_mpageN; p++) for (int r = 0; r < g_mpage[p].n; r++) if (strcmp(g_mpage[p].row[r].key, key) == 0) return g_mpage[p].row[r].kind;
    return -1;
}
void MenuOnValue(const char* key, int iv, float fv, void*) {
    if (!key || !key[0]) return;
    const int kind = MenuKind(key);
    const float v = (kind == MENU_TOGGLE) ? (float)iv : fv;
    if (!std::isfinite(v)) return;
    char one[96]; snprintf(one, sizeof(one), "%s=%.4g;", key, v);
    MenuLock();
    if (strlen(g_mqueue) + strlen(one) < sizeof(g_mqueue) - 1) strcat(g_mqueue, one);
    MenuUnlock();
    if (MenuVal* m = MenuFind(key)) m->v = v;        // (the row shows what was set until the Lua confirms it)
    Log("menu: %s -> %.4g", key, v);
}
int MenuOnGet(const char* key, int* oi, float* of, void*) {
    MenuVal* m = (key && key[0]) ? MenuFind(key) : nullptr;
    if (!m) return 0;
    if (oi) *oi = (int)(m->v + (m->v >= 0.0f ? 0.5f : -0.5f));
    if (of) *of = m->v;
    return 1;
}
bool PageIsSub(int idx);                        // (the host block, below)
OmpRegisterPage2Fn g_seamReg = nullptr;         // (v66) SessionOpenMP's seam when it is loaded: the fall-back for our own pages
int MenuRegisterFlat();
int MenuRegister() {
    if (g_mreg != 0) return g_mreg;
    if (g_mpageN < 1) return 0;
    OmpRegisterPage2Fn reg = nullptr;                 // the host: whichever loaded module exports the seam
    HMODULE mods[512]; DWORD need = 0;
    if (EnumProcessModules(GetCurrentProcess(), mods, sizeof(mods), &need)) {
        const int n = (int)((need / sizeof(HMODULE)) < 512 ? (need / sizeof(HMODULE)) : 512);
        for (int i = 0; i < n && !reg; i++) reg = (OmpRegisterPage2Fn)GetProcAddress(mods[i], "OmpMenu_RegisterPage2");
    }
    g_seamReg = reg;
    if (g_menuOwn) {                                  // (v66) MenuOwnPages=1 (the default): our own NESTED pages, with or without SessionOpenMP
        g_host = 1; g_mreg = 2;
        Log("menu: our own nested pause-menu pages%s", reg ? " (SessionOpenMP's menu is loaded too: ours go in front of its hooks; its one flat page is the fall-back)" : "");
        return g_mreg;
    }
    if (!reg) {
        if (++g_mtries < 3) return 0;                    // (mods.txt order decides who loads first; three looks a second apart is plenty)
        g_host = 1; g_mreg = 2;                           // (v44) no SessionOpenMP: our own host, installed on the game thread's next frame
        Log("menu: no SessionOpenMP menu host loaded -- our own pause-menu pages will be used");
        return g_mreg;
    }
    return MenuRegisterFlat();
}
// (v66) the one flat page through SessionOpenMP's seam: what MenuOwnPages=0 asks for, and the fall-back when our own nested
// pages cannot be placed
int MenuRegisterFlat() {
    OmpRegisterPage2Fn reg = g_seamReg;
    if (!reg) { g_mreg = -1; return g_mreg; }
    // (v45) ONE page through the seam. SessionOpenMP's page table holds 16 and SessionTweaks takes 15 of them, so the
    // nested layout (four pages) cannot be had there: every toggle and slider goes on one flat page, 14 rows at most
    // (what the panel is laid out for), each key once. The nested pages are our own host's, with no other mod loaded.
    static OmpPageItem2 flat[MENU_ROWS]; int n = 0; const char* title = "Expanded Tricks";
    int mainIdx = -1;
    for (int p = 0; p < g_mpageN && mainIdx < 0; p++) if (!PageIsSub(p)) mainIdx = p;
    if (mainIdx >= 0) title = g_mpage[mainIdx].title;
    for (int p = 0; p < g_mpageN; p++) {
        if (p == mainIdx) continue;
        for (int r = 0; r < g_mpage[p].n && n < 14; r++) {
            const MenuRow& w = g_mpage[p].row[r];
            if (w.kind != MENU_TOGGLE && w.kind != MENU_SLIDER) continue;
            bool dup = false;
            for (int i = 0; i < n; i++) if (strcmp(flat[i].key, w.key) == 0) dup = true;
            if (dup) continue;
            OmpPageItem2 it = { w.kind, w.key, w.label, w.desc[0] ? w.desc : nullptr, w.off[0] ? w.off : nullptr, w.on[0] ? w.on : nullptr, w.lo, w.hi, w.step };
            flat[n++] = it;
        }
    }
    if (n < 1) { g_mreg = -1; return g_mreg; }
    const int ok = reg(title, flat, n, nullptr, &MenuOnValue, &MenuOnGet, nullptr, nullptr);
    g_mreg = ok ? 1 : -1;
    if (ok) Log("menu: one flat page \"%s\" of %d rows registered with SessionOpenMP's menu (its page table has room for one of ours; the nested pages are the mod's own host's)", title, n);
    else Log("menu: SessionOpenMP's menu refused the page \"%s\" (%d rows): its page table is full -- the settings stay in the ini", title, n);
    return g_mreg;
}
void CopyStr(char* dst, size_t cap, const std::string& s) { snprintf(dst, cap, "%s", s.c_str()); }
// HJN_MenuPage(title) -> the page's number (rows added after this go to it); "" = forget every page (a reload)
int nMenuPage(const Lua& lua) {
    std::string t; ArgStr(lua, t);
    if (t.empty()) { g_mpageN = 0; g_mvalN = 0; lua.set_integer(0); return 1; }
    if (g_mreg == 1 || g_mpageN >= MENU_PAGES) { lua.set_integer(0); return 1; }
    MenuPage& pg = g_mpage[g_mpageN++];
    memset(&pg, 0, sizeof(pg));
    CopyStr(pg.title, sizeof(pg.title), t);
    lua.set_integer(g_mpageN);
    return 1;
}
// HJN_MenuRow(kind 1 toggle / 2 slider / 3 page, key, label, description, min, max, step, off label, on label) -> rows on the page
int nMenuRow(const Lua& lua) {
    double kind = 0, lo = 0, hi = 1, step = 1; std::string key, label, desc, off, on;
    ArgNum(lua, kind); ArgStr(lua, key); ArgStr(lua, label); ArgStr(lua, desc); ArgNum(lua, lo); ArgNum(lua, hi); ArgNum(lua, step); ArgStr(lua, off); ArgStr(lua, on);
    if (g_mreg == 1 || g_mpageN < 1 || key.empty()) { lua.set_integer(0); return 1; }
    MenuPage& pg = g_mpage[g_mpageN - 1];
    if (pg.n >= MENU_ROWS) { lua.set_integer(pg.n); return 1; }
    MenuRow& w = pg.row[pg.n++];
    memset(&w, 0, sizeof(w));
    w.kind = (int)kind; CopyStr(w.key, sizeof(w.key), key); CopyStr(w.label, sizeof(w.label), label.empty() ? key : label);
    CopyStr(w.desc, sizeof(w.desc), desc); CopyStr(w.off, sizeof(w.off), off); CopyStr(w.on, sizeof(w.on), on);
    w.lo = (float)lo; w.hi = (float)hi; w.step = (float)step;
    lua.set_integer(pg.n);
    return 1;
}
// HJN_MenuValue(key, value) -> 1: what the row shows (in the row's own units)
int nMenuValue(const Lua& lua) {
    std::string key; double v = 0;
    ArgStr(lua, key); ArgNum(lua, v);
    if (key.empty() || !std::isfinite(v)) { lua.set_integer(0); return 1; }
    MenuVal* m = MenuFind(key.c_str());
    if (!m) { if (g_mvalN >= MENU_VALS) { lua.set_integer(0); return 1; } m = &g_mval[g_mvalN++]; CopyStr(m->key, sizeof(m->key), key); }
    m->v = (float)v;
    lua.set_integer(1);
    return 1;
}
int SafeMenuRegister() { __try { return MenuRegister(); } __except (GrabFilter(GetExceptionCode())) { g_mreg = -1; Log("fault registering the menu pages -- the settings stay in the ini"); return -1; } }
// HJN_MenuRegister() -> 1 the pages are in the pause menu, 0 no host yet (ask again later), -1 no host (given up)
int nMenuRegister(const Lua& lua) { lua.set_integer(SafeMenuRegister()); return 1; }
// HJN_MenuTake() -> "key=value;key=value;..." the player's changes since the last call (in the rows' units)
int nMenuTake(const Lua& lua) {
    char out[sizeof(g_mqueue)];
    MenuLock();
    snprintf(out, sizeof(out), "%s", g_mqueue);
    g_mqueue[0] = 0;
    MenuUnlock();
    lua.set_string(out);
    return 1;
}

// ==== (v44) OUR OWN PAUSE-MENU HOST =====================================================================
// Stage 2: "Expanded Tricks" in the game's pause menu with no other mod loaded. The design and every measured
// fact below are SessionOpenMP's (src/ui/pause_menu.cpp and game_syms.h, GPLv3, matsix), cut down to what a
// settings page needs; where its code is used, the licence follows it.
//   * Session's menus are data: a UMenuPageDefinition holds a TArray<FMenuPageItemDefinition> (144 B each) and
//     UMenuPage::CreatePageItems turns that array into one row widget each. The hook hands it a DIFFERENT array,
//     one we own and never free -- so the engine never destructs anything of ours.
//   * Our sub-pages are FAKE: the engine's page stays the pause root; we swap the rows it builds from and set the
//     title. A swap is QUEUED and run a frame later from the engine tick (never inside the confirm callback, whose
//     caller is still walking the row widgets), and the engine tick runs paused or not.
//   * Rows are known by their FName key. Toggles are the game's MultiOption row, sliders its ProgressBar row; their
//     values are stamped onto the WIDGETS after each rebuild (the definition's copy does not survive the rebuild).
//   * An FText is a refcounted handle: built once from an FName (FText::FromName), copied bitwise into our rows and
//     never destructed; the one handed BY VALUE to SetTitle gets its refcount bumped first (the callee releases it).
//   * A zeroed FText is a null pointer with a crash attached: every text field of a row gets a real one.
// HOOKS. No hooking library in this tree, so a detour of our own: the target's first N bytes -- chosen by hand from
// the disassembly so that no relative instruction is displaced, and checked against the bytes found -- go to a
// trampoline followed by a jump back, and the target gets `jmp [rip+0]; <hook>` in their place. Two of the targets
// are 32-byte funnels with a branch in their first bytes, so the hook RE-IMPLEMENTS them (test a flag, stamp the
// page definition into the params, broadcast the delegate) instead of trampolining. Installed on the game thread.
uintptr_t RVA_MENU_CREATEITEMS = 0x1071150;   // UMenuPage::CreatePageItems(this, const TArray<FMenuPageItemDefinition>&, bool)
uintptr_t RVA_MENU_SELCONFIRM  = 0x1090c80;   // UMenuPage::OnSelectionConfirmed(this, params&)        -- re-implemented
uintptr_t RVA_MENU_BACKACTION  = 0x1076df0;   // UMenuPageContainer::HandlePageBackAction(this, params)
uintptr_t RVA_MENU_MULTICHG    = 0x10822e0;   // UMenuPage::OnMultiOptionItemSelectionChanged(this, params&)
uintptr_t RVA_MENU_PROGCHG     = 0x1090c50;   // UMenuPage::OnProgressBarValueChanged(this, params&)    -- re-implemented
uintptr_t RVA_MENU_REFRESH     = 0x1096b70;   // UMenuPage::RefreshItemsPanel(this)
uintptr_t RVA_MENU_SETTITLE    = 0x109ab60;   // UMenuPage::SetTitle(this, FText by value)
uintptr_t RVA_MENU_SETSEL      = 0x1099eb0;   // UMenuPage::SetSelectedIndex(this, int, bool)
uintptr_t RVA_ITEM_PROGSET     = 0x1096330;   // UMenuPageItem::ProgressBarSetPercent(this, float 0..1)
uintptr_t RVA_ITEM_MULTISET    = 0x1078e80;   // UMenuPageItem::MultiOptionSetSelectedItemIndex(this, int)
uintptr_t RVA_DELEGATE_BCAST   = 0x7e5920;    // TMulticastDelegate<void(Params&)>::Broadcast(this, params&) -- the funnels' tail call
uintptr_t RVA_FNAME_CTOR_A     = 0x132d4e0;   // FName::FName(const char*, EFindName)
uintptr_t RVA_FTEXT_FROMNAME   = 0x126d3f0;   // FText::FromName(const FName&)
uintptr_t RVA_ENGINE_TICK      = 0x2c2c000;   // UGameEngine::Tick(this, float, bool) -- the pump
constexpr int PG_FLAGS = 0x2b0, PG_MAXVISIBLE = 0x290, PG_ACTIVEDEF = 0x298, PG_WIDGETS = 0x2a0, PG_HEADERIDX = 0x2b4, PG_SELIDX = 0x2b8;
constexpr int PG_DLG_CONFIRM = 0x3b0, PG_DLG_PROGRESS = 0x398;      // the two funnels' delegates
constexpr int DEF_KEY = 0x30, DEF_DISPLAYNAME = 0x38;
constexpr int IT_SIZE = 0x90, IT_KEY = 0x00, IT_PLATFORMS = 0x08, IT_EDITORONLY = 0x0c, IT_TYPE = 0x0d, IT_LABEL = 0x10, IT_SHORT = 0x28,
              IT_LONG = 0x40, IT_DELAY = 0x60, IT_MULTITEXTS = 0x68, IT_MULTISTART = 0x78, IT_PMIN = 0x80, IT_PMAX = 0x84, IT_PINC = 0x88;
constexpr int PRM_ITEM = 0x08, PRM_NEW = 0x9c, CONT_PAGE = 0x2a0;
struct FTextBlob { uint8_t b[24]; };
struct TArrayHdr { void* data; int32_t num; int32_t max; };
typedef void  (*FNameCtorFn)(uint64_t* self, const char* s, int find);
typedef void* (*TextFromNameFn)(FTextBlob* out, const uint64_t* name);
typedef void  (*MenuCreateFn)(void* page, const void* items, bool flag);
typedef void  (*MenuParamsFn)(void* page, void* params);
typedef void  (*MenuBackFn)(void* container, void* pageDef);
typedef void  (*MenuRefreshFn)(void* page);
typedef void  (*MenuSetTitleFn)(void* page, const FTextBlob* text);
typedef void  (*MenuSetSelFn)(void* page, int32_t idx, bool flag);
typedef void  (*ItemFloatFn)(void* item, float v);
typedef void  (*ItemIntFn)(void* item, int32_t v);
typedef void  (*BroadcastFn)(void* delegate, void* params);
typedef void  (*EngineTickFn)(void* engine, float dt, bool idle);
// ---- the detour ----
uint8_t* g_trampPage = nullptr; size_t g_trampUsed = 0;
bool DetourPatch(uint8_t* target, const void* hook, int n, const uint8_t* expect, int nExpect, const char* name) {
    if (memcmp(target, expect, nExpect) != 0) { Log("menu host: %s does not start with the bytes expected -- not hooked", name); return false; }
    DWORD old = 0;
    if (!VirtualProtect(target, n, PAGE_EXECUTE_READWRITE, &old)) { Log("menu host: %s could not be unprotected", name); return false; }
    uint8_t patch[32]; memset(patch, 0x90, sizeof(patch));
    patch[0] = 0xFF; patch[1] = 0x25; *(int32_t*)(patch + 2) = 0; *(uint64_t*)(patch + 6) = (uint64_t)hook;
    memcpy(target, patch, n);
    DWORD tmp = 0; VirtualProtect(target, n, old, &tmp);
    FlushInstructionCache(GetCurrentProcess(), target, n);
    return true;
}
// n bytes displaced into a trampoline (n >= 14, an instruction boundary, nothing relative among them)
void* DetourInstall(uint8_t* target, const void* hook, int n, const uint8_t* expect, int nExpect, const char* name) {
    if (!g_trampPage) g_trampPage = (uint8_t*)VirtualAlloc(nullptr, 4096, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!g_trampPage || g_trampUsed + n + 14 > 4096) return nullptr;
    if (memcmp(target, expect, nExpect) != 0) { Log("menu host: %s does not start with the bytes expected -- not hooked", name); return nullptr; }
    uint8_t* t = g_trampPage + g_trampUsed;
    memcpy(t, target, n);
    t[n] = 0xFF; t[n + 1] = 0x25; *(int32_t*)(t + n + 2) = 0; *(uint64_t*)(t + n + 6) = (uint64_t)(target + n);
    if (!DetourPatch(target, hook, 14, expect, nExpect, name)) return nullptr;
    g_trampUsed += n + 14;
    Log("menu host: %s hooked (%d bytes displaced)", name, n);
    return t;
}
// (v138) THE MONSTER'S FEET: THE ANIMATION'S OWN FOOT ANCHORS WHILE THE DECK TUMBLES. "His feet are now glued to the board during
// the flip ... his legs just twist like pretzels" (19 Oct, build 239: SessionTweaks' log had the foot targets going round a
// 30 cm circle with the deck). USkaterAnimInstance::UpdateFootAnchors asks GetFootIKData (once a foot) for the foot's target:
// in the air that is the trick animation's foot anchor (the skeleton's Foot_Anchor bone, component space) re-attached to the
// REAL deck -- the anchor's place relative to the skeleton's board bone, put on the real deck (its lambda @0xf4b0b0). In the
// game's own flips the animation's board and the real one flip together, so the target IS the anchor: the feet are the
// animation's. Under a monster or a dolphin the real deck tumbles end over end while your kickflip's animation rolls its own
// board, and the targets went round with the real deck. So while one turns, the target this hook hands back is the anchor
// itself (its own place and turn), in the share the deck is off the feet (AltFeetW: off over the turn's first 30 deg, back
// as the real deck comes within 38..8 deg of upright for the catch): the rest is the game's (its catch, its smoothing,
// SessionTweaks' stick push after it, the foot IK). Arguments read off the two calls in UpdateFootAnchors: (this, dt,
// catch info, the deck-attached target, the anchor, the catch socket, bool, last turn, out place, out turn, alpha, float).
// Epic's exe only (the bytes are checked): on another build no hook, and the legs are drawn as before (GameFeet()).
constexpr uintptr_t RVA_FOOTIKDATA = 0xf57de0;   // void USkaterAnimInstance::GetFootIKData(float, const FCatchFootInfo&, const FTransform&, const FTransform&, const FTransform&, bool, const FQuat&, FVector&, FQuat&, float&, float&) const
typedef void (*FootIKDataFn)(const void* self, float dt, const void* ci, const void* defXf, const void* ancXf, const void* catXf, bool b, const void* prevQ, float* outLoc, float* outRot, float* alpha, float* f2);
FootIKDataFn o_FootIK = nullptr;
bool FaApply(const float* anc, float* loc, float* rot, float w) {   // POD only (the caller's __try): FTransform = rotation (0), translation (+0x10), scale (+0x20)
    const float qx = anc[0], qy = anc[1], qz = anc[2], qw = anc[3], ax = anc[4], ay = anc[5], az = anc[6];
    if (!std::isfinite(qx + qy + qz + qw + ax + ay + az) || !std::isfinite(loc[0] + loc[1] + loc[2] + rot[0] + rot[1] + rot[2] + rot[3])) return false;
    const float ql = qx * qx + qy * qy + qz * qz + qw * qw;
    if (fabsf(ql - 1.0f) > 0.05f) return false;
    loc[0] += (ax - loc[0]) * w; loc[1] += (ay - loc[1]) * w; loc[2] += (az - loc[2]) * w;
    const float s = (qx * rot[0] + qy * rot[1] + qz * rot[2] + qw * rot[3]) < 0.0f ? -1.0f : 1.0f;
    float r[4] = { rot[0] + (s * qx - rot[0]) * w, rot[1] + (s * qy - rot[1]) * w, rot[2] + (s * qz - rot[2]) * w, rot[3] + (s * qw - rot[3]) * w };
    const float rl = sqrtf(r[0] * r[0] + r[1] * r[1] + r[2] * r[2] + r[3] * r[3]);
    if (!(rl > 1.0e-4f)) return false;
    rot[0] = r[0] / rl; rot[1] = r[1] / rl; rot[2] = r[2] / rl; rot[3] = r[3] / rl;
    return true;
}
bool SafeFaApply(const float* anc, float* loc, float* rot, float w) {
    __try { return FaApply(anc, loc, rot, w); }
    __except (EXCEPTION_EXECUTE_HANDLER) { g_faOn = 0; g_faW = 0.0f; return false; }
}
void FpPush(const uint8_t* self, float* loc, const float* alpha, float w) {   // (242) POD only (the caller's __try): the foot's push, the popping foot's or the other's
    const bool right = (const uint8_t*)alpha == self + 0x684, left = (const uint8_t*)alpha == self + 0x680;   // the right foot's call hands the anim's +0x684, the left's +0x680
    if (!right && !left) return;
    const float* P = ((right ? 1 : 0) == g_fpPopR) ? g_fpPop : g_fpFlick;
    const float x = loc[0] + P[0] * w, y = loc[1] + P[1] * w, z = loc[2] + P[2] * w;
    if (!std::isfinite(x + y + z)) return;
    loc[0] = x; loc[1] = y; loc[2] = z;
    if (InterlockedIncrement(&g_fpN) == 1) Log("alt flips: the flick's push laid on the game's foot targets (the first: %.0f %% of it on the %s foot)", w * 100.0f, right ? "right" : "left");
}
void SafeFpPush(const uint8_t* self, float* loc, const float* alpha, float w) {
    __try { FpPush(self, loc, alpha, w); }
    __except (EXCEPTION_EXECUTE_HANDLER) { g_fpW = 0.0f; g_fpSteer = 0.0f; }
}
void UfFoot(const uint8_t* self, float* loc, const float* alpha, float w) {   // (253) POD only (the caller's __try): the underflip's foot (the note at UfStep)
    const bool right = (const uint8_t*)alpha == self + 0x684, left = (const uint8_t*)alpha == self + 0x680;   /* the MESH's feet (as FpPush) */
    if ((!right && !left) || (right ? 1 : 0) != (int)g_ufR) return;
    const float x = loc[0] + (g_ufP[0] - loc[0]) * w, y = loc[1] + (g_ufP[1] - loc[1]) * w, z = loc[2] + (g_ufP[2] - loc[2]) * w;
    if (!std::isfinite(x + y + z)) return;
    loc[0] = x; loc[1] = y; loc[2] = z;
    if (InterlockedIncrement(&g_ufN) == 1) Log("alt flips: the underflip's foot laid on the game's foot target (the first: %.0f %% of it, the %s foot)", w * 100.0f, right ? "right" : "left");
}
void SafeUfFoot(const uint8_t* self, float* loc, const float* alpha, float w) {
    __try { UfFoot(self, loc, alpha, w); }
    __except (EXCEPTION_EXECUTE_HANDLER) { g_ufW = 0.0f; g_altUnderLeg = 0; }
}
void HfFoot(const uint8_t* self, const float* anc, float* loc, float* rot, const float* alpha, float w) {   /* (255) POD only (the caller's __try): the hospital's foot (the note at HospFeetStep) */
    const bool right = (const uint8_t*)alpha == self + 0x684, left = (const uint8_t*)alpha == self + 0x680;   /* the MESH's feet (as FpPush) */
    if (!right && !left) return;
    const int f = right ? 1 : 0;
    if (!std::isfinite(loc[0] + loc[1] + loc[2] + rot[0] + rot[1] + rot[2] + rot[3])) return;
    if (w <= 0.001f) {                             /* a casper on, no turn: its target recorded */
        if (g_hfRec) { for (int i = 0; i < 3; i++) g_hfHold[f][i] = loc[i]; for (int i = 0; i < 4; i++) g_hfHold[f][3 + i] = rot[i]; g_hfHoldOk[f] = 1; }
        const float cw = g_hcW;                    /* (259) the alternate casper: the back foot off the board (the note at HcStep) */
        if (cw > 0.001f && f == g_hcFoot) {
            const float c1 = cw > 1.0f ? 1.0f : cw, lx = loc[0] + g_hcL[0] * c1, ly = loc[1] + g_hcL[1] * c1, lz = loc[2] + g_hcL[2] * c1;
            if (std::isfinite(lx + ly + lz)) { loc[0] = lx; loc[1] = ly; loc[2] = lz; }
        }
        return;
    }
    const bool held = g_hfHoldOk[f] != 0; const float* H = g_hfHold[f];
    const float ax = anc[4], ay = anc[5], az = anc[6];
    if (!std::isfinite(ax + ay + az)) return;
    const float k = g_hfK;
    const float hc = (held && f == g_hcFoot && g_hcWf > 0.001f) ? (g_hcWf > 1.0f ? 1.0f : g_hcWf) : 0.0f;   /* (259) the alternate casper's lifted back foot, eased to the anchor with the place */
    const float h0 = H[0] + g_hcL[0] * hc, h1 = H[1] + g_hcL[1] * hc, h2 = H[2] + g_hcL[2] * hc;
    float p[3] = { held ? h0 + (ax - h0) * k : ax, held ? h1 + (ay - h1) * k : ay, held ? h2 + (az - h2) * k : az };
    if (f == g_hfFront && g_hfBack > 0.01f) { const float bk = g_hfBack * k; p[0] -= g_hfA[0] * bk; p[1] -= g_hfA[1] * bk; }   /* (262) the front foot back toward the back foot, before the push (the note at HospToeFront) */
    const float R = g_hfR;
    if (R > 1.0f) {                                /* out of the circle the turning deck sweeps (its middle, its long axis flat, the up) */
        const float A0 = g_hfA[0], A1 = g_hfA[1], vx = p[0] - g_hfC[0], vy = p[1] - g_hfC[1], vz = p[2] - g_hfC[2];
        const float a = vx * A0 + vy * A1, r = sqrtf(a * a + vz * vz);
        if (r < R) {   /* eased in with the place (k): no jump at the flick */
            if (r > 1.0f) { const float s = (R / r - 1.0f) * k; p[0] += A0 * a * s; p[1] += A1 * a * s; p[2] += vz * s; }
            else p[2] += R * k;
        }
    }
    if (f == g_hzF && g_hzM > 0.0f) {             /* (263) the front foot kept behind the rising face, last (the note at HospGuardStep) */
        const float vx = p[0] - g_hzC[0], vy = p[1] - g_hzC[1], vz = p[2] - g_hzC[2], a = vx * g_hzA[0] + vy * g_hzA[1];
        const float sa = a * g_hzE[0] + vz * g_hzE[1], h = a * g_hzN[0] + vz * g_hzN[1];
        if (sa > -5.0f && h > -g_hzM && std::isfinite(sa + h)) { const float dh = -g_hzM - h; p[0] += g_hzA[0] * g_hzN[0] * dh; p[1] += g_hzA[1] * g_hzN[0] * dh; p[2] += g_hzN[1] * dh; InterlockedIncrement(&g_hzHits); if (-dh > g_hzMost) g_hzMost = -dh; }
    }
    if (!std::isfinite(p[0] + p[1] + p[2])) return;
    const float q[4] = { held ? H[3] : anc[0], held ? H[4] : anc[1], held ? H[5] : anc[2], held ? H[6] : anc[3] };   /* the turn: the casper's (sole down) */
    const float ql = q[0] * q[0] + q[1] * q[1] + q[2] * q[2] + q[3] * q[3];
    if (!(fabsf(ql - 1.0f) <= 0.05f)) return;
    const float sg = (q[0] * rot[0] + q[1] * rot[1] + q[2] * rot[2] + q[3] * rot[3]) < 0.0f ? -1.0f : 1.0f;
    const float r4[4] = { rot[0] + (sg * q[0] - rot[0]) * w, rot[1] + (sg * q[1] - rot[1]) * w, rot[2] + (sg * q[2] - rot[2]) * w, rot[3] + (sg * q[3] - rot[3]) * w };
    const float rl = sqrtf(r4[0] * r4[0] + r4[1] * r4[1] + r4[2] * r4[2] + r4[3] * r4[3]);
    if (!(rl > 1.0e-4f)) return;
    for (int i = 0; i < 3; i++) loc[i] += (p[i] - loc[i]) * w;
    for (int i = 0; i < 4; i++) rot[i] = r4[i] / rl;
    if (InterlockedIncrement(&g_hfN) == 1) Log("alt flips: the hospital's feet laid on the game's foot targets (the first: share %.2f, the %s foot, %s)", w, right ? "right" : "left", held ? "from its casper target" : "no casper target recorded: the anchor");
}
void SafeHfFoot(const uint8_t* self, const float* anc, float* loc, float* rot, const float* alpha, float w) {
    __try { HfFoot(self, anc, loc, rot, alpha, w); }
    __except (EXCEPTION_EXECUTE_HANDLER) { g_hfW = 0.0f; g_hospFeet = 0; g_hcW = 0.0f; g_hcWf = 0.0f; g_hcOn = 0; }
}
void hkFootIK(const void* self, float dt, const void* ci, const void* defXf, const void* ancXf, const void* catXf, bool b, const void* prevQ, float* outLoc, float* outRot, float* alpha, float* f2) {
    o_FootIK(self, dt, ci, defXf, ancXf, catXf, b, prevQ, outLoc, outRot, alpha, f2);
    const float w = g_faW;
    if (w > 0.001f && g_faOn && FpLive() && self && self == g_faAnim && ancXf && outLoc && outRot) {   /* (243) FpLive */
        if (SafeFaApply((const float*)ancXf, outLoc, outRot, w > 1.0f ? 1.0f : w)) {
            if (InterlockedIncrement(&g_faN) == 1) Log("alt flips: the monster's / dolphin's foot targets are the animation's own anchors while the deck tumbles (the first one given, share %.2f)", w);
        }
        else if (g_faOn == 0) Log("alt flips: a fault reading the game's foot targets -- the GetFootIKData hook stands down: the legs are drawn by the mod for the rest of this run");
    }
    const float pw = g_fpW;   // (242) the flick's push (the note at FpStep), whatever the share above
    if (pw > 0.001f && g_faOn && FpLive() && self && self == g_faAnim && outLoc && alpha) SafeFpPush((const uint8_t*)self, outLoc, alpha, pw > 1.0f ? 1.0f : pw);
    const float uw = g_ufW;   /* (253) an underflip's foot (the note at UfStep); 0 for every other trick */
    if (uw > 0.001f && g_faOn && FpLive() && self && self == g_faAnim && outLoc && alpha) SafeUfFoot((const uint8_t*)self, outLoc, alpha, uw > 1.0f ? 1.0f : uw);
    const float hw = g_hfW;   /* (255) the hospital's feet (the note at HospFeetStep); 0 and no casper for every other trick */
    if ((hw > 0.001f || g_hfRec || g_hcW > 0.001f) && g_faOn && FpLive() && self && self == g_faAnim && ancXf && outLoc && outRot && alpha) SafeHfFoot((const uint8_t*)self, (const float*)ancXf, outLoc, outRot, alpha, hw > 1.0f ? 1.0f : hw);
}
void FaInstall() {
    static const uint8_t expect[21] = { 0x48, 0x8B, 0xC4, 0x48, 0x89, 0x58, 0x08, 0x48, 0x89, 0x68, 0x10, 0x48, 0x89, 0x70, 0x18, 0x48, 0x89, 0x78, 0x20, 0x41, 0x56 };
    if (o_FootIK) return;
    o_FootIK = (FootIKDataFn)DetourInstall(Exe() + RVA_FOOTIKDATA, (const void*)&hkFootIK, 21, expect, sizeof(expect), "USkaterAnimInstance::GetFootIKData (the monster's feet)");
    g_faOn = o_FootIK ? 1 : 0;
    Log(o_FootIK ? "the monster's / dolphin's feet: GetFootIKData hooked -- while the deck tumbles their targets are your flip animation's own foot anchors"
                 : "the monster's / dolphin's feet: GetFootIKData NOT hooked (its bytes are not the ones expected) -- the legs are drawn by the mod as before build 239");
}
// (242) THE BOARD'S FRAME LEFT ALONE: THE BORROWED FLIP ANIMATION'S EMPTY FLIP, REFUSED. "During the monster flip, the board is going
// absolutely crazy ... way too many flips and like twists ... it's just supposed to go end over end with a slight off kilter axis.
// Same with the dolphin flip" (19 Oct, build 241). Since build 239 your kickflip's / heelflip's animation plays in a monster's /
// dolphin's air (the feet), and those clips carry the game's board-flip notify (AnimNotify_SkaterboardFlip, 0.21 s in): it calls
// ASkaterCharacterBase::FlipBoard with the flip of the trick being done -- the OLLIE's, which has none (TargetAngle 0: angle 0, speed
// 0) -- and the ollie's ForceAutoCatch caught that empty flip at once (UpdateBoardTargetFlipAndScoop: the flip over, auto catching).
// A caught board in the air gets the game's catch yaw align (PhysFalling): the rider frame (bm+0x5c0, the frame the mod's pitch target
// is built on) eased toward the board's own axis, turned 180 whenever the deck reads reversed -- which an end-over-end tumble does at
// every pass through vertical. The frame swung 150-180 deg each pass (the recordings of builds 239-241, up to ~1000 deg/s about vertical;
// build 238, before the borrowed clip: within 12 deg). So while a monster / dolphin is in the air (phase 2, kind 1) a flip of less than
