    if (!(w > 0.0005f) || !mesh || GetTickCount64() > g_wrBt.at + 250ull) return false;
    const Q4 q = qnorm(*(const Q4*)(mesh + SC_C2W)); const V3 t = *(const V3*)(mesh + SC_C2W + 0x10), s = *(const V3*)(mesh + SC_C2W + 0x20);
    if (!finite3(*r) || !finite3(t) || !finite3(s) || !std::isfinite(q.w) || fabsf(s.x) < 1e-3f || fabsf(s.y) < 1e-3f || fabsf(s.z) < 1e-3f) return false;
    const V3 pl = qinv(q, sub(*r, t));
