            if (fabsf(pm.x - px) <= WR_BT_XY_MATCH && fabsf(pm.y - py) <= WR_BT_XY_MATCH) { pm.x -= ddx; pm.y -= ddy; g_wrBtXyN = g_wrBtXyN + 1; }
