constexpr int AD_CUE = 0x30, AD_VOL0 = 0x38, AD_VOL1 = 0x3c, AD_PIT0 = 0x40, AD_PIT1 = 0x44, AD_WEAR = 0x499;   // the audio data: the cue, the curves, WearAndDirtIndex
